 "tip.luck": "到目前为止你的预期损失约为{e}；净收益为{n}。差额是运气——轮数越多差距越小。",
 "tip.bot": "{n}每输一次就把下注翻倍（现在{a}）。马丁格尔法不会改变庄家优势——只会让罕见的大输更大。",
 "tipg.1": "按基本策略打，庄家优势可降到约0.5%——赌场里最划算的游戏之一。",
 "tipg.2": "庄家2–6“容易爆牌”，7–A“强”。拿不准时先看庄家的牌。",
 "tipg.3": "12–16是“僵牌”：庄家牌强时要牌，弱时停牌。",
 "tipg.4": "11是最好的加倍。10也加倍，除非庄家是10点牌或A。",
 "tipg.5": "A和8总是分，10和5永远不分——基本策略的口诀。",
 "tipg.6": "只有剩余牌中10点牌超过三分之一时保险才划算。正常牌靴约30%，所以不买。",
 "tipg.7": "学庄家打（要到17）会让庄家优势约5.5%——是基本策略的十倍以上（见“研究”）。",
 "tipg.8": "“绝不爆牌”（12以上一律停牌）也要损失约4–6%。该停时停，该要时要。",
 "tipg.9": "软牌（A算11）再拿一张不会爆。软17及以下要牌或加倍。",
 "tipg.10": "黑杰克赔6:5的牌桌比3:2多损失约1.4%。看清桌面上的标示。",
 "tipg.11": "庄家软17要牌（H17）比S17让你多损失约0.2%。",
 "tipg.12": "Hi-Lo：2–6 = +1，7–9 = 0，10点牌和A = −1。计数越高，剩下的10点牌和A越多——对你有利。",
 "tipg.13": "真数 = 流水计数 ÷ 剩余副数。真数每+1，玩家约多+0.5%。",
 "tipg.14": "算牌并不违法，但赌场不喜欢。在这里它是理解游戏原理的方法。",
 "tipg.15": "Sam在算牌：只在计数高时下大注。留意他的下注。",
 "tipg.16": "Lin按基本策略平注，Aiko“绝不爆牌”，Marco用马丁格尔法。时间一长差距就显现了。",
 "tipg.17": "投降能在很差的牌上省下一半（硬16对9、10点牌、A；15对10点牌）。少见但重要。",
 "tipg.18": "边注的庄家优势在3–6%以上——比主注贵得多。",
 "tipg.19": "连输不会改变下一张牌（计数除外）。不要加注想赢回来。",
 "tipg.20": "开始前先定好止损线——最有效的资金管理。",
 "tipv.classic": "维加斯规则：庄家软17停牌（可更改），可以投降——基本策略的标准玩法。",
 "tipv.european": "欧式：庄家是10点牌或A时，少加倍少分牌——庄家黑杰克会连追加的筹码一起拿走。",
 "tipv.spanish": "西班牙21点：10点牌更少，加倍和分牌要比普通21点少。",
 "tipv.free": "免费下注：免费的加倍和分牌一定要用——它们能弥补庄家22点平局的损失。",
