 "r.classic.origin": "18世纪法国（Vingt-et-un）",
 "r.classic.players": "1–7名玩家 + 庄家",
 "r.classic.time": "每轮约1分钟",
 "r.classic.hist": "21点源自法国的“Vingt-et-un”（二十一），后在美国流行。据说“Blackjack”这个名字来自一项促销：黑桃A配黑色J可额外获奖。1960年代数学家索普发表了算牌法，21点因此作为“可以战胜的赌场游戏”而闻名。",
 "r.classic.win": "在不超过21点的前提下比庄家更接近21点。超过21点即“爆牌”，判负。前两张为A和10点牌（黑杰克）赔3:2。",
 "r.classic.cult": "全球赌场最受欢迎的桌面游戏——也是少有的讲究技术的游戏：正确的打法（基本策略）能让庄家优势保持很小。",
 "r.classic.facts": "10、J、Q、K算10点；A算1或11|庄家16点以下要牌，17点以上停牌|你可以选择：要牌、停牌、加倍、分牌",
 "r.classic.p": [
  {
   "t": "计算点数",
   "b": "2–9按数字计算；10、J、Q、K都算10点。",
   "task": "K和7是几点？",
   "ok": "正确：K是10，所以10 + 7 = 17。",
   "ng": "J、Q、K都算10点。"
  },
  {
   "t": "A是1或11",
   "b": "A可算1或11，取有利的一种。把A算作11的手牌叫“软牌”。",
   "task": "A和6是几点？",
   "ok": "正确——7或17，即“软17”。再拿一张也不会爆。",
   "ng": "A可以算1或11。"
  },
  {
   "t": "黑杰克",
   "b": "前两张为A和10点牌（10、J、Q、K）即为“黑杰克”——最强的牌。赔3:2。",
   "task": "你下注$100并拿到黑杰克。能赢多少？",
   "ok": "正确！3:2就是1.5倍：$150。",
   "ng": "黑杰克赔3:2（1.5倍）。"
  },
  {
   "t": "爆牌",
   "b": "超过21点即“爆牌”，无论庄家如何都立即判负。",
   "task": "10 + 6 + 9 = 25。这手牌……",
   "ok": "正确：超过21——爆牌，你输了。",
   "ng": "超过21点立即判负。"
  },
  {
   "t": "庄家的规则",
   "b": "庄家没有选择：16点以下要牌，17点以上停牌。",
   "task": "庄家是K和6 = 16。会怎样？",
   "ok": "正确：16点以下，庄家必须要牌。",
   "ng": "庄家16点以下一定要牌。"
  },
  {
   "t": "加倍",
   "b": "拿到前两张后，可以把赌注加倍并只再拿一张牌。在你占优时使用。",
   "task": "6 + 5 = 11，庄家明牌是6。最佳操作是？",
   "ok": "正确！11常能凑成21，庄家的6又容易爆——完美的加倍时机。",
   "ng": "11对6正是加倍的时候。"
  },
  {
   "t": "分牌",
   "b": "两张点数相同的牌，可以再加同样的赌注分成两手。",
   "task": "8和8（16）对庄家9。你怎么做？",
   "ok": "正确：16是最差的牌——分成两手从8开始的牌。",
   "ng": "8一定要分。"
  },
  {
   "t": "保险",
   "b": "庄家明牌是A时，可以用一半赌注为黑杰克投保——长期来看是亏损的下注。",
   "task": "保险赔多少？",
   "ok": "正确：2:1。底牌是10点牌的概率只有约30%，所以通常不买。",
   "ng": "保险赔2:1。"
  }
 ],
 "r.european.origin": "欧洲赌场",
 "r.european.players": "1–7名玩家 + 庄家",
 "r.european.time": "每轮约1分钟",
 "r.european.hist": "欧洲和澳大利亚的常见玩法。没有底牌，偷看底牌作弊更难。",
 "r.european.win": "与维加斯规则相同，只是庄家起初只拿一张牌，等所有玩家结束后再拿第二张。",
 "r.european.cult": "许多欧洲赌场只允许9–11加倍。面对10点牌或A时要谨慎。",
 "r.european.facts": "庄家没有底牌|庄家黑杰克连加倍和分牌的赌注也一起拿走|9–11可加倍，不可投降",
 "r.european.p": [
  {
   "t": "没有底牌",
   "b": "庄家起初只拿一张明牌，等所有玩家结束后才拿第二张。",
   "task": "庄家什么时候拿第二张牌？",
   "ok": "正确——所以加倍前你无法知道庄家是否是黑杰克。",
   "ng": "第二张牌在玩家之后。"
  },
  {
   "t": "黑杰克通吃",
   "b": "如果庄家之后做成黑杰克，加倍和分牌追加的筹码也会输掉。",
   "task": "你把$100加倍并做成20点。庄家翻出10和A。你输多少？",
   "ok": "正确：整整$200。所以对10点牌或A时要少加倍。",
   "ng": "加倍的筹码也会输掉。"
  }
 ],
 "r.spanish.origin": "西班牙风格，美国赌场",
 "r.spanish.players": "1–7名玩家 + 庄家",
 "r.spanish.time": "每轮约1分钟",
 "r.spanish.hist": "受西班牙纸牌（没有10）启发的21点变体。1990年代在美国赌场流行开来。",
 "r.spanish.win": "去掉10来玩，这对玩家不利——作为补偿，玩家21点必胜，5张以上的21点或6-7-8有奖金。",
 "r.spanish.cult": "任意张数可加倍、分开的A可要牌等宽松规则，让牌局更加热闹。",
 "r.spanish.facts": "每副48张（去掉4张10）|玩家21点和黑杰克必胜|5张牌21点赔3:2；6-7-8和7-7-7有奖金",
 "r.spanish.p": [
  {
   "t": "没有10的牌",
   "b": "每副牌去掉4张10（J、Q、K保留）。10点牌变少，对玩家略不利。",
   "task": "一副牌有几张？",
   "ok": "正确：52 − 4 = 48。",
   "ng": "从52张中去掉4张10。"
  },
  {
   "t": "21点必胜",
   "b": "玩家的21点即使对上庄家的21点也赢（庄家黑杰克除外）。",
   "task": "你用5张牌做成21，庄家用3张做成21。结果是？",
   "ok": "正确！21点必胜——而且5张牌21点还有3:2奖金。",
   "ng": "西班牙21点中玩家21点必胜。"
  },
  {
   "t": "奖金21点",
   "b": "6-7-8或7-7-7组成的21点有奖金：同花2:1，黑桃3:1。",
   "task": "梅花6-7-8。下注$100赢多少？",
   "ok": "正确：同花6-7-8赔2:1——$200。",
   "ng": "同花6-7-8赔2:1。"
  }
 ],
 "r.free.origin": "拉斯维加斯（2010年代）",
 "r.free.players": "1–7名玩家 + 庄家",
 "r.free.time": "每轮约1分钟",
 "r.free.hist": "2010年代诞生于拉斯维加斯的新型21点。“免费加倍、免费分牌”让人容易喜欢，并传遍了全世界。",
 "r.free.win": "硬9–11加倍和除10以外所有对子的分牌免费：赌场会加上一枚“免费筹码”，赢了照样赔付，但永远不会输掉。",
 "r.free.cult": "作为代价，庄家最终为22点时，所有未爆牌的手牌为平局。免费筹码有就要用。",
 "r.free.facts": "硬9、10、11免费加倍|除10以外所有对子免费分牌|庄家22点为平局（黑杰克仍然赢）",
 "r.free.p": [
  {
   "t": "免费加倍",
   "b": "硬9、10或11时，赌场用免费筹码替你加倍。",
   "task": "你下注$100，手牌6 + 4 = 10。加倍要花多少？",
   "ok": "正确：不花钱。赢了得$200，输了只输$100。",
   "ng": "硬9–11加倍是免费的。"
  },
  {
   "t": "庄家的22点",
   "b": "作为代价，庄家最终恰好22点时，所有未爆牌的手牌为平局。",
   "task": "你是18点；庄家做成10 + 6 + 6 = 22。结果是？",
   "ok": "正确：平时是赢，但在免费下注中22点为平局。",
   "ng": "庄家22点为平局。"
  },
  {
   "t": "免费分牌",
   "b": "除10以外的所有对子都可以不加钱分牌（免费筹码）。",
   "task": "8和8对10点牌。你怎么做？",
   "ok": "正确！免费得到两手牌。",
   "ng": "除10以外所有对子的分牌都免费。"
  }
 ],
