 "l.value": "手牌点数",
 "lp.value": "10、J、Q、K为10；A为1或11",
 "ld.value": "快速算出几张牌的点数。",
 "x.value": "2–9按数字计算；10、J、Q、K算10点。\nA算11，若会超过21点则算1。",
 "ltip.value": "先把10点牌加起来——更快。",
 "l.soft": "软牌与硬牌",
 "lp.soft": "A可算作11的手牌",
 "ld.soft": "识别软牌——它们的打法很不一样。",
 "x.soft": "能把A算作11且不超过21点的手牌叫“软牌”（A + 6 = 软17）。\n软牌再拿一张不会爆。A只能算1的手牌叫“硬牌”。",
 "ltip.soft": "A + 6 + 10：A算11会变成27，所以是硬17。",
 "l.pay": "赔付",
 "lp.pay": "普通赢1:1，黑杰克3:2",
 "ld.pay": "黑杰克、加倍、投降和保险各赔多少。",
 "x.pay": "普通赢赔一倍赌注（1:1）；黑杰克赔1.5倍（3:2）；平局退回赌注。\n加倍赢了赔两倍赌注；投降输一半；保险赔2:1。",
 "ltip.pay": "在6:5的牌桌，黑杰克只赔1.2倍。",
 "l.dealer": "庄家的规则",
 "lp.dealer": "16以下要牌，17以上停牌",
 "ld.dealer": "判断庄家是否要牌。注意软17。",
 "x.dealer": "庄家没有选择：16点以下要牌，17点以上停牌。\n软17（A + 6）停牌为S17，要牌为H17——桌面上会写明。",
 "ltip.dealer": "庄家爆牌的概率约为28%。",
 "l.hard": "硬牌",
 "lp.hard": "8–16时要牌、停牌还是加倍",
 "ld.hard": "按庄家明牌，学习没有A的手牌的基本策略。",
 "x.hard": "11点以下不会爆：要牌或加倍。11是绝佳的加倍时机。\n12–16时，大致是庄家牌弱（2–6）停牌，强（7–A）要牌。",
 "ltip.hard": "拿不准时，先问：庄家的牌是弱（2–6）还是强（7–A）？",
 "l.stiff": "僵牌",
 "lp.stiff": "12–16：要牌还是停牌？",
 "ld.stiff": "容易爆的牌——由庄家的牌决定。",
 "x.stiff": "12–16要牌容易爆，停牌又弱。\n庄家牌弱（2–6）时停牌，等庄家爆；庄家牌强（7–A）时要牌。例外：12对2或3要牌。",
 "ltip.stiff": "16对10点牌这样的坏牌：能投降就投降——拿回一半最好。",
 "l.softs": "软牌",
 "lp.softs": "A+2到A+8的打法",
 "ld.softs": "何时用不会爆的牌进攻。",
 "x.softs": "软牌再拿一张不会爆，所以要比硬牌更多地要牌。\n软17及以下绝不停牌；庄家牌弱时加倍。软18要看庄家的牌。",
 "ltip.softs": "软18（A+7）对9、10点牌或A要牌。",
 "l.pairs": "对子分牌",
 "lp.pairs": "分A和8，不分10和5",
 "ld.pairs": "哪些对子对哪些庄家牌要分。",
 "x.pairs": "A和8总是分。10（20点）和5（10点）永远不分。\n其他对子主要在庄家牌弱时分。",
 "ltip.pairs": "一对9（18点）对7、10点牌或A时停牌。",
 "l.insurance": "保险",
 "lp.insurance": "庄家明牌A时的保险",
 "ld.insurance": "保险和等额赔付的真正价值。",
 "x.insurance": "保险是押底牌为10点牌的2:1下注。\n正常牌靴中概率约30%——不到三分之一（33%），所以长期会亏。",
 "ltip.insurance": "算牌者只在真数+3以上时买保险。",
 "l.sidebets": "边注",
 "lp.sidebets": "完美对子和21+3",
 "ld.sidebets": "说出牌型和赔率。",
 "x.sidebets": "完美对子：前两张点数相同——同花色25:1，同颜色12:1，不同颜色6:1。\n21+3：你的两张牌加庄家明牌组成扑克牌型——同花5:1，顺子10:1，三条30:1…",
 "ltip.sidebets": "边注的庄家优势在3–6%以上。小额就好。",
 "l.variants": "各种变体",
 "lp.variants": "欧式、西班牙21点、免费下注",
 "ld.variants": "四种玩法有何不同，对打法有什么影响。",
 "x.variants": "欧式：没有底牌；之后的黑杰克连加倍也拿走。\n西班牙21点：没有10，但21点必胜且有奖金。免费下注：免费加倍和分牌，庄家22点为平局。",
 "ltip.variants": "规则不同，策略表也不同——在“研究”里比较。",
 "l.edge": "庄家优势",
 "lp.edge": "规则的价值",
 "ld.edge": "S17与H17、3:2与6:5、牌副数……每条规则的代价。",
 "x.edge": "庄家优势是长期来看你会输掉的下注比例——按基本策略约0.5%。\n6:5约多1.4%，H17约多0.2%；牌副越少略有利。",
 "ltip.edge": "凭感觉而不按基本策略打，优势会升到好几个百分点。",
 "l.hilo": "Hi-Lo点值",
 "lp.hilo": "2–6为+1，10点牌和A为−1",
 "ld.hilo": "立即说出每张牌的计数值。",
 "x.hilo": "Hi-Lo：小牌（2–6）为+1，7–9为0，大牌（10、J、Q、K、A）为−1。\n小牌出得越多，剩下的10点牌和A越多——对玩家有利。",
 "ltip.hilo": "一整副牌的计数正好是0。",
