 "o.fixed.spanish": "고정 규칙: 48장 덱(10 없음). 몇 장이든 더블 가능, 스플릿한 에이스도 히트·재스플릿 가능. 플레이어의 21과 블랙잭은 항상 승리. 보너스: 5장 21 3:2, 6장 2:1, 7장 이상 3:1, 6-7-8 / 7-7-7 3:2(같은 무늬 2:1, 스페이드 3:1).",
 "o.fixed.free": "고정 규칙: 하드 9–11 더블과 10을 제외한 모든 페어의 스플릿이 무료(프리 칩은 절대 잃지 않음). 딜러가 22로 끝나면 살아 있는 모든 핸드는 푸시(블랙잭은 그대로 승리).",
