 "tipg.4": "11은 최고의 더블. 10도 더블이지만 딜러가 10이나 에이스면 예외.",
 "tipg.5": "에이스와 8은 항상 스플릿, 10과 5는 절대 스플릿하지 않기 — 기본 전략의 좌우명.",
 "tipg.6": "인슈어런스는 남은 카드의 3분의 1 이상이 10일 때만 이득입니다. 보통 슈에서는 약 30%이니 거절하세요.",
 "tipg.7": "딜러처럼 플레이(17까지 히트)하면 하우스 엣지가 약 5.5% — 기본 전략의 10배 이상입니다(‘연구’ 참고).",
 "tipg.8": "‘절대 버스트 안 하기’(12 이상 무조건 스탠드)도 약 4–6% 손해입니다. 멈출 때와 받을 때가 있습니다.",
 "tipg.9": "소프트 핸드(에이스를 11로 셈)는 한 장으로 버스트하지 않습니다. 소프트 17 이하는 히트나 더블.",
 "tipg.10": "블랙잭 6:5 테이블은 3:2보다 약 1.4% 더 손해입니다. 테이블 표시를 확인하세요.",
 "tipg.11": "소프트 17에서 히트하는 딜러(H17)는 S17보다 약 0.2% 손해입니다.",
 "tipg.12": "Hi-Lo: 2–6 = +1, 7–9 = 0, 10과 에이스 = −1. 카운트가 높을수록 10과 에이스가 많이 남아 있어 유리합니다.",
 "tipg.13": "트루 카운트 = 러닝 카운트 ÷ 남은 덱 수. 트루 카운트 +1마다 플레이어에게 약 +0.5%.",
 "tipg.14": "카드 카운팅은 불법은 아니지만 카지노는 싫어합니다. 여기서는 게임의 원리를 배우는 방법입니다.",
 "tipg.15": "Sam은 카드를 셉니다: 카운트가 높을 때만 크게 겁니다. 그의 베팅을 지켜보세요.",
 "tipg.16": "Lin은 고정 베팅으로 기본 전략, Aiko는 ‘절대 버스트 안 하기’, Marco는 마틴게일. 시간이 지나면 차이가 드러납니다.",
 "tipg.17": "서렌더는 아주 나쁜 핸드에서 절반을 지켜 줍니다(하드 16 대 9·10·에이스, 15 대 10). 드물지만 중요합니다.",
 "tipg.18": "사이드 베팅의 하우스 엣지는 3–6% 이상 — 메인 베팅보다 훨씬 비쌉니다.",
 "tipg.19": "연패해도 다음 카드는 바뀌지 않습니다(카운트 제외). 되찾으려고 베팅을 올리지 마세요.",
 "tipg.20": "시작 전에 손절선을 정하세요 — 가장 효과적인 자금 관리입니다.",
 "tipv.classic": "베가스 스트립: 딜러는 소프트 17에서 스탠드(변경 가능), 서렌더 가능 — 기본 전략의 표준 게임.",
 "tipv.european": "유럽식: 딜러가 10이나 에이스면 더블과 스플릿을 줄이세요 — 딜러 블랙잭이 추가한 돈까지 가져갑니다.",
 "tipv.spanish": "스패니시 21: 10이 적으므로 일반 블랙잭보다 더블과 스플릿을 덜 하세요.",
 "tipv.free": "프리 벳: 무료 더블과 스플릿은 항상 하세요 — 딜러 22 푸시로 잃는 만큼을 되찾아 줍니다.",
