 "r.classic.players": "1–7명 + 딜러",
 "r.classic.time": "라운드당 약 1분",
 "r.classic.hist": "블랙잭은 프랑스의 ‘Vingt-et-un’(21)에서 유래해 미국에서 퍼졌습니다. 이름은 스페이드 에이스와 검은 잭에 추가 배당을 준 홍보에서 왔다고 합니다. 1960년대 수학자 소프가 카드 카운팅을 발표하면서, 블랙잭은 ‘이길 수 있는 카지노 게임’으로 유명해졌습니다.",
 "r.classic.win": "21을 넘지 않고 딜러보다 21에 가까워지세요. 21을 넘으면 ‘버스트’로 패배. 처음 두 장이 에이스와 10(블랙잭)이면 3:2 배당.",
 "r.classic.cult": "전 세계 카지노에서 가장 인기 있는 테이블 게임이자, 실력이 통하는 드문 게임입니다: 올바른 플레이(기본 전략)로 하우스 엣지를 작게 유지할 수 있습니다.",
 "r.classic.facts": "10, J, Q, K는 10; 에이스는 1 또는 11|딜러는 16 이하 히트, 17 이상 스탠드|선택지: 히트, 스탠드, 더블, 스플릿",
