 "tip.luck": "Tu pérdida esperada hasta ahora es de unos {e}; tu neto es {n}. La diferencia es suerte, y se reduce a medida que suman las rondas.",
 "tip.bot": "{n} dobla la apuesta tras cada derrota (ahora {a}). La martingala no cambia la ventaja de la casa: solo hace más grande la rara pérdida enorme.",
 "tipg.1": "Jugar la estrategia básica reduce la ventaja de la casa a cerca del 0,5%: uno de los juegos más baratos del casino.",
 "tipg.2": "Un crupier con 2–6 «se pasa a menudo», con 7–as es «fuerte». Si dudas, mira primero la carta del crupier.",
 "tipg.3": "12–16 son manos «duras de jugar»: pide contra una carta fuerte del crupier y plántate contra una débil.",
 "tipg.4": "11 es el mejor doble. 10 también se dobla, salvo contra un diez o un as.",
 "tipg.5": "Divide siempre ases y 8; nunca dieces ni 5: el lema de la estrategia básica.",
 "tipg.6": "El seguro solo compensa cuando más de una de cada tres cartas restantes son dieces. En un zapato normal es un 30%, así que di que no.",
 "tipg.7": "Jugar como el crupier (pedir hasta 17) da a la casa cerca del 5,5%, más de diez veces la ventaja con estrategia básica (ver Estudio).",
 "tipg.8": "«No pasarse nunca» (plantarse con 12+) también cuesta un 4–6%. Hay momentos para plantarse y momentos para pedir.",
 "tipg.9": "Una mano blanda (un as contado como 11) no se pasa con una carta. Pide o dobla con 17 blando o menos.",
 "tipg.10": "Una mesa con blackjack 6:5 cuesta un 1,4% más que una 3:2. Mira el cartel del tapete.",
 "tipg.11": "Un crupier que pide con 17 blando (H17) te cuesta un 0,2% respecto a S17.",
 "tipg.12": "Hi-Lo: 2–6 = +1, 7–9 = 0, dieces y ases = −1. Cuanto más alto el conteo, más dieces y ases quedan: bueno para ti.",
 "tipg.13": "Conteo real = conteo corriente ÷ barajas restantes. Cada +1 de conteo real vale un +0,5% para el jugador.",
 "tipg.14": "Contar cartas no es ilegal, pero a los casinos no les gusta. Aquí es una forma de entender cómo funciona el juego.",
 "tipg.15": "Sam cuenta cartas: solo apuesta fuerte cuando el conteo es alto. Fíjate en sus apuestas.",
 "tipg.16": "Lin juega la estrategia básica con apuesta fija, Aiko «no se pasa nunca», Marco juega la martingala. Con el tiempo se nota la diferencia.",
 "tipg.17": "La rendición ahorra la mitad en manos muy malas (16 duro contra 9, diez o as; 15 contra un diez). Rara pero importante.",
 "tipg.18": "Las apuestas laterales tienen ventajas de la casa del 3–6% o más: mucho más caras que la principal.",
 "tipg.19": "Una racha perdedora no cambia la siguiente carta (salvo por el conteo). No subas la apuesta para recuperar.",
 "tipg.20": "Decide tu límite de pérdida antes de empezar: la gestión del dinero que mejor funciona.",
 "tipv.classic": "Vegas Strip: el crupier se planta con 17 blando (modificable), se permite rendirse: el juego estándar de la estrategia básica.",
 "tipv.european": "Europeo: contra un diez o un as del crupier, dobla y divide menos; un blackjack del crupier se lleva también el dinero extra.",
 "tipv.spanish": "Spanish 21: con menos dieces, dobla y divide menos que en el blackjack normal.",
 "tipv.free": "Free Bet: aprovecha siempre los dobles y divisiones gratis; recuperan lo que se lleva el empate por el 22 del crupier.",
