 "tip.bot": "{n} double la mise après chaque défaite (maintenant {a}). La martingale ne change pas l'avantage de la maison — elle rend juste la rare grosse perte encore plus grosse.",
 "tipg.1": "Jouer la stratégie de base ramène l'avantage de la maison à environ 0,5 % — l'un des jeux les moins chers du casino.",
 "tipg.2": "Un croupier sur 2–6 « saute souvent », sur 7–as il est « fort ». En cas de doute, regardez d'abord la carte du croupier.",
