 "tipg.11": "Un croupier qui tire sur 17 souple (H17) vous coûte environ 0,2 % par rapport à S17.",
 "tipg.12": "Hi-Lo : 2–6 = +1, 7–9 = 0, dix et as = −1. Plus le compte est haut, plus il reste de dix et d'as — bon pour vous.",
 "tipg.13": "Compte réel = compte courant ÷ jeux restants. Chaque +1 de compte réel vaut environ +0,5 % pour le joueur.",
 "tipg.14": "Compter les cartes n'est pas illégal, mais les casinos n'aiment pas ça. Ici, c'est un moyen de comprendre comment fonctionne le jeu.",
 "tipg.15": "Sam compte les cartes : il ne mise gros que quand le compte est élevé. Observez ses mises.",
 "tipg.16": "Lin joue la stratégie de base à mise fixe, Aiko « ne saute jamais », Marco joue la martingale. Avec le temps, la différence se voit.",
 "tipg.17": "L'abandon sauve la moitié sur les très mauvaises mains (16 dur contre 9, dix, as ; 15 contre un dix). Rare mais important.",
 "tipg.18": "Les paris annexes ont un avantage de la maison de 3–6 % ou plus — bien plus chers que la mise principale.",
 "tipg.19": "Une série de défaites ne change pas la carte suivante (sauf via le compte). Ne montez pas la mise pour vous refaire.",
 "tipg.20": "Fixez votre limite de perte avant de commencer — la gestion d'argent qui marche le mieux.",
 "tipv.classic": "Vegas Strip : le croupier reste sur 17 souple (modifiable), abandon autorisé — le jeu standard de la stratégie de base.",
 "tipv.european": "Européen : contre un dix ou un as du croupier, doublez et séparez moins — un blackjack du croupier emporte aussi l'argent en plus.",
 "tipv.spanish": "Spanish 21 : avec moins de dix, doublez et séparez moins souvent qu'au blackjack ordinaire.",
 "tipv.free": "Free Bet : prenez toujours les doubles et séparations gratuits — ils compensent ce que coûte l'égalité sur le 22 du croupier.",
