 "r.classic.origin": "France, XVIIIe siècle (Vingt-et-un)",
 "r.classic.players": "1–7 joueurs + croupier",
 "r.classic.time": "environ 1 min par tour",
 "r.classic.hist": "Le blackjack vient du « Vingt-et-un » français et s'est répandu en Amérique. Son nom viendrait d'une promotion qui payait un bonus pour un as de pique avec un valet noir. Dans les années 1960, le mathématicien Thorp a publié le comptage des cartes, et le blackjack est devenu célèbre comme le jeu de casino qu'on peut battre.",
 "r.classic.win": "Approchez-vous plus de 21 que le croupier sans dépasser. Au-delà de 21, c'est « bust » (vous sautez) et vous perdez. Un as et un dix en deux premières cartes (blackjack) paie 3:2.",
 "r.classic.cult": "Le jeu de table le plus populaire des casinos du monde entier — et l'un des rares où l'habileté compte : le bon jeu (la stratégie de base) garde l'avantage de la maison très bas.",
 "r.classic.facts": "10, V, D, R valent 10 ; l'as 1 ou 11|Le croupier tire jusqu'à 16 et reste à 17+|À vous de choisir : tirer, rester, doubler, séparer",
 "r.classic.p": [
  {
   "t": "Compter les cartes",
   "b": "De 2 à 9, les cartes valent leur chiffre ; 10, V, D et R valent tous 10.",
   "task": "Combien font R et 7 ?",
   "ok": "Exact : R vaut 10, donc 10 + 7 = 17.",
   "ng": "V, D et R valent 10."
  },
  {
   "t": "L'as vaut 1 ou 11",
   "b": "L'as vaut 1 ou 11, selon ce qui arrange. Une main où l'as compte 11 est « souple ».",
   "task": "Combien font A et 6 ?",
   "ok": "Exact — 7 ou 17, un « 17 souple ». Il ne peut pas sauter avec une carte de plus.",
   "ng": "Un as peut valoir 1 ou 11."
  },
  {
   "t": "Blackjack",
   "b": "Un as et une carte de valeur dix (10, V, D, R) en deux premières cartes font un « blackjack » — la meilleure main. Il paie 3:2.",
   "task": "Vous misez $100 et avez un blackjack. Combien gagnez-vous ?",
   "ok": "Exact ! 3:2, c'est 1,5 fois : $150.",
   "ng": "Un blackjack paie 3:2 (1,5 fois)."
  },
  {
   "t": "Bust",
   "b": "Au-delà de 21, c'est « bust » : vous perdez aussitôt, quoi que fasse le croupier.",
   "task": "10 + 6 + 9 = 25. Cette main…",
   "ok": "Exact : plus de 21 — bust, vous perdez.",
   "ng": "Au-delà de 21, on perd tout de suite."
  },
  {
   "t": "La règle du croupier",
   "b": "Le croupier n'a pas le choix : il tire jusqu'à 16 et reste à 17 ou plus.",
   "task": "Le croupier a R et 6 = 16. Que se passe-t-il ?",
   "ok": "Exact : 16 ou moins, le croupier doit tirer.",
   "ng": "Le croupier tire toujours à 16 ou moins."
  },
  {
   "t": "Doubler",
   "b": "Après les deux premières cartes, vous pouvez doubler votre mise et recevoir exactement une carte de plus. À utiliser quand vous êtes devant.",
   "task": "6 + 5 = 11, le croupier montre un 6. Le meilleur coup ?",
   "ok": "Exact ! 11 fait souvent 21 et le 6 du croupier saute souvent — un double parfait.",
   "ng": "11 contre un 6, c'est le moment de doubler."
  },
  {
   "t": "Séparer",
   "b": "Deux cartes de même rang peuvent être séparées en deux mains en ajoutant une mise identique.",
   "task": "8 et 8 (16) contre un 9 du croupier. Que faites-vous ?",
   "ok": "Exact : 16 est la pire main — séparez en deux mains qui partent de 8.",
   "ng": "Séparez toujours les 8."
  },
  {
   "t": "Assurance",
   "b": "Quand le croupier montre un as, vous pouvez vous assurer contre un blackjack pour la moitié de votre mise — un pari perdant à long terme.",
   "task": "Combien paie l'assurance ?",
   "ok": "Exact : 2:1. La carte cachée n'est un dix qu'environ 30 % du temps, donc dites généralement non.",
   "ng": "L'assurance paie 2:1."
  }
 ],
 "r.european.origin": "Casinos européens",
 "r.european.players": "1–7 joueurs + croupier",
 "r.european.time": "environ 1 min par tour",
 "r.european.hist": "Le jeu habituel en Europe et en Australie. Sans carte cachée, il est plus difficile de tricher en la regardant.",
 "r.european.win": "Comme à Las Vegas, sauf que le croupier ne reçoit d'abord qu'une carte et tire la seconde après tous les joueurs.",
 "r.european.cult": "Beaucoup de casinos européens n'autorisent le doublement que sur 9–11. Face à un dix ou un as, jouez prudemment.",
 "r.european.facts": "Pas de carte cachée pour le croupier|Un blackjack du croupier emporte aussi les mises doublées et séparées|Doublement sur 9–11, pas d'abandon",
 "r.european.p": [
  {
   "t": "Pas de carte cachée",
   "b": "Le croupier reçoit d'abord une carte face visible, et la seconde seulement quand tous les joueurs ont fini.",
   "task": "Quand le croupier reçoit-il sa seconde carte ?",
   "ok": "Exact — vous ne pouvez donc pas savoir s'il a un blackjack avant de doubler.",
   "ng": "La seconde carte vient après les joueurs."
  },
  {
   "t": "Le blackjack rafle tout",
   "b": "Si le croupier fait ensuite un blackjack, l'argent ajouté en doublant ou en séparant est perdu aussi.",
   "task": "Vous avez doublé $100 et fait 20. Le croupier retourne un dix et un as. Que perdez-vous ?",
   "ok": "Exact : les $200 entiers. Donc doublez moins contre un dix ou un as.",
   "ng": "L'argent doublé est perdu aussi."
  }
 ],
 "r.spanish.origin": "Style espagnol, casinos américains",
 "r.spanish.players": "1–7 joueurs + croupier",
 "r.spanish.time": "environ 1 min par tour",
 "r.spanish.hist": "Une variante du blackjack inspirée du jeu de cartes espagnol (qui n'a pas de 10). Elle s'est répandue dans les casinos américains dans les années 1990.",
 "r.spanish.win": "Se joue sans les 10, ce qui pénalise le joueur — en échange, un 21 du joueur gagne toujours et les 21 à 5+ cartes ou en 6-7-8 rapportent des bonus.",
 "r.spanish.cult": "Doubler avec n'importe quel nombre de cartes, tirer sur des as séparés et d'autres règles généreuses rendent les mains animées.",
 "r.spanish.facts": "48 cartes par jeu (les quatre 10 retirés)|Le 21 et le blackjack du joueur gagnent toujours|21 à 5 cartes paie 3:2 ; bonus pour 6-7-8 et 7-7-7",
 "r.spanish.p": [
  {
   "t": "Un jeu sans 10",
   "b": "Chaque jeu perd ses quatre 10 (V, D, R restent). Moins de cartes de valeur dix, c'est un peu moins bien pour le joueur.",
   "task": "Combien de cartes dans un jeu ?",
   "ok": "Exact : 52 − 4 = 48.",
   "ng": "On retire les quatre 10 des 52 cartes."
  },
  {
   "t": "21 gagne toujours",
   "b": "Un 21 du joueur gagne même contre un 21 du croupier (sauf un blackjack du croupier).",
   "task": "Vous faites 21 en 5 cartes ; le croupier fait 21 en 3. Résultat ?",
   "ok": "Exact ! 21 gagne toujours — et un 21 à 5 cartes paie un bonus de 3:2.",
   "ng": "Au Spanish 21, le 21 du joueur gagne toujours."
  },
  {
   "t": "21 à bonus",
   "b": "Un 21 en 6-7-8 ou 7-7-7 paie un bonus : 2:1 assorti, 3:1 à pique.",
   "task": "6-7-8 de trèfle. Que gagne une mise de $100 ?",
   "ok": "Exact : un 6-7-8 assorti paie 2:1 — $200.",
   "ng": "Un 6-7-8 assorti paie 2:1."
  }
 ],
