 "tips.less": "Menos",
 "tip.luck": "Sua perda esperada até agora é cerca de {e}; seu saldo é {n}. A diferença é sorte — ela diminui com o passar das rodadas.",
 "tip.bot": "{n} dobra a aposta depois de cada derrota (agora {a}). A Martingale não muda a vantagem da casa — só deixa a rara grande perda ainda maior.",
 "tipg.1": "Jogar a estratégia básica reduz a vantagem da casa para cerca de 0,5% — um dos jogos mais baratos do cassino.",
 "tipg.2": "Um 2–6 do dealer “estoura com frequência”, 7–ás é “forte”. Na dúvida, olhe primeiro a carta do dealer.",
 "tipg.3": "12–16 são mãos “duras de jogar”: peça contra carta forte do dealer, pare contra carta fraca.",
 "tipg.4": "11 é a melhor mão para dobrar. Com 10 também se dobra, exceto contra dez ou ás.",
 "tipg.5": "Sempre divida ases e 8; nunca divida dez ou 5 — o lema da estratégia básica.",
 "tipg.6": "O seguro só compensa quando mais de uma em três das cartas restantes é dez. Num sapato normal é cerca de 30%, então diga não.",
 "tipg.7": "Jogar como o dealer (pedir até 17) dá à casa cerca de 5,5% — mais de dez vezes a vantagem com a estratégia básica (veja Estudo).",
 "tipg.8": "“Nunca estourar” (parar com qualquer 12+) também custa cerca de 4–6%. Há hora de parar e hora de pedir.",
 "tipg.9": "Uma mão suave (um ás contado como 11) não estoura com uma carta. Peça ou dobre com 17 suave ou menos.",
 "tipg.10": "Uma mesa de blackjack 6:5 custa cerca de 1,4% a mais que 3:2. Confira o aviso no feltro.",
 "tipg.11": "Um dealer que pede no 17 suave (H17) custa cerca de 0,2% a mais que S17.",
 "tipg.12": "Hi-Lo: 2–6 = +1, 7–9 = 0, dez e ases = −1. Quanto maior a contagem, mais dez e ases restam — bom para você.",
 "tipg.13": "Contagem real = contagem corrente ÷ baralhos restantes. Cada +1 de contagem real vale cerca de +0,5% para o jogador.",
 "tipg.14": "Contar cartas não é ilegal, mas os cassinos não gostam. Aqui é uma forma de aprender como o jogo funciona.",
 "tipg.15": "Sam conta cartas: ele só aposta alto quando a contagem está alta. Observe as apostas dele.",
 "tipg.16": "Lin joga a estratégia básica com aposta fixa, Aiko “nunca estoura”, Marco usa a Martingale. Com o tempo a diferença aparece.",
 "tipg.17": "Desistir salva metade em mãos muito ruins (16 duro contra 9, dez, ás; 15 contra dez). Raro, mas importante.",
 "tipg.18": "As apostas paralelas têm vantagem da casa de 3–6% ou mais — bem mais caras que a aposta principal.",
 "tipg.19": "Uma sequência de derrotas não muda a próxima carta (exceto pela contagem). Não aumente a aposta para recuperar.",
 "tipg.20": "Defina seu stop-loss antes de começar — a gestão de dinheiro que funciona melhor.",
 "tipv.classic": "Las Vegas Strip: o dealer para no 17 suave (ajustável), desistência permitida — o jogo padrão da estratégia básica.",
 "tipv.european": "Europeu: contra dez ou ás do dealer, dobre e divida menos — um blackjack do dealer leva também o dinheiro extra.",
 "tipv.spanish": "Spanish 21: com menos dez, dobre e divida menos que no blackjack comum.",
 "tipv.free": "Free Bet: sempre aproveite as dobras e divisões grátis — elas compensam o que o empate no 22 do dealer tira.",
