 "tips.more": "Mehr Tipps ({n})",
 "tips.less": "Weniger",
 "tip.luck": "Dein erwarteter Verlust bisher liegt bei etwa {e}; deine Bilanz ist {n}. Der Unterschied ist Glück — er schrumpft mit jeder Runde.",
 "tip.bot": "{n} verdoppelt nach jeder Niederlage (jetzt {a}). Die Martingale ändert den Hausvorteil nicht — sie macht nur den seltenen großen Verlust größer.",
 "tipg.1": "Mit der Grundstrategie sinkt der Hausvorteil auf etwa 0,5 % — eines der günstigsten Spiele im Casino.",
 "tipg.2": "Eine 2–6 beim Dealer „überkauft sich oft“, 7–Ass ist „stark“. Im Zweifel zuerst auf die Dealerkarte schauen.",
 "tipg.3": "12–16 sind „Stiff“-Hände: gegen eine starke Dealerkarte Karte, gegen eine schwache stehen.",
 "tipg.4": "11 ist das beste Verdoppeln. Auch 10 wird verdoppelt, außer gegen Zehn oder Ass.",
 "tipg.5": "Asse und 8er immer teilen; Zehner und 5er nie — das Motto der Grundstrategie.",
 "tipg.6": "Die Versicherung lohnt sich nur, wenn mehr als ein Drittel der restlichen Karten Zehner sind. In einem normalen Schuh sind es etwa 30 % — also nein.",
 "tipg.7": "Wie der Dealer zu spielen (Karte bis 17) gibt dem Haus etwa 5,5 % — über zehnmal so viel wie mit Grundstrategie (siehe Lernen).",
 "tipg.8": "„Nie überkaufen“ (bei jeder 12+ stehen) kostet auch etwa 4–6 %. Es gibt Zeit zum Stehen und Zeit zum Ziehen.",
 "tipg.9": "Eine Soft-Hand (Ass als 11 gezählt) kann sich mit einer Karte nicht überkaufen. Bei Soft 17 und weniger ziehen oder verdoppeln.",
 "tipg.10": "Ein 6:5-Blackjack-Tisch kostet etwa 1,4 % mehr als 3:2. Achte auf die Aufschrift auf dem Filz.",
 "tipg.11": "Ein Dealer, der bei Soft 17 zieht (H17), kostet dich etwa 0,2 % gegenüber S17.",
 "tipg.12": "Hi-Lo: 2–6 = +1, 7–9 = 0, Zehner und Asse = −1. Je höher der Zählstand, desto mehr Zehner und Asse sind übrig — gut für dich.",
 "tipg.13": "True Count = Running Count ÷ verbleibende Decks. Jedes +1 True Count bringt dem Spieler etwa +0,5 %.",
 "tipg.14": "Kartenzählen ist nicht verboten, aber Casinos mögen es nicht. Hier ist es ein Weg, das Spiel zu verstehen.",
 "tipg.15": "Sam zählt Karten: Er setzt nur hoch, wenn der Zählstand hoch ist. Achte auf seine Einsätze.",
 "tipg.16": "Lin spielt Grundstrategie mit festem Einsatz, Aiko „überkauft sich nie“, Marco spielt Martingale. Mit der Zeit zeigt sich der Unterschied.",
 "tipg.17": "Aufgeben rettet bei sehr schlechten Händen die Hälfte (harte 16 gegen 9, Zehn, Ass; 15 gegen Zehn). Selten, aber wichtig.",
 "tipg.18": "Nebenwetten haben 3–6 % Hausvorteil oder mehr — viel teurer als der Haupteinsatz.",
 "tipg.19": "Eine Pechsträhne ändert die nächste Karte nicht (außer über den Zählstand). Erhöhe nicht, um es zurückzuholen.",
 "tipg.20": "Leg dein Stop-Loss vor dem Start fest — das Geldmanagement, das am besten funktioniert.",
 "tipv.classic": "Vegas Strip: Der Dealer steht bei Soft 17 (änderbar), Aufgeben erlaubt — das Standardspiel hinter der Grundstrategie.",
 "tipv.european": "Europäisch: Gegen Zehn oder Ass des Dealers weniger verdoppeln und teilen — ein Dealer-Blackjack nimmt auch das zusätzliche Geld.",
 "tipv.spanish": "Spanish 21: Mit weniger Zehnern seltener verdoppeln und teilen als im normalen Blackjack.",
 "tipv.free": "Free Bet: Nimm die Gratis-Verdopplungen und -Teilungen immer mit — sie holen zurück, was das Unentschieden bei 22 kostet.",
