 "r.classic.origin": "Frankreich, 18. Jh. (Vingt-et-un)",
 "r.classic.players": "1–7 Spieler + Dealer",
 "r.classic.time": "ca. 1 Min. pro Runde",
 "r.classic.hist": "Blackjack stammt vom französischen „Vingt-et-un“ (einundzwanzig) und verbreitete sich in Amerika. Der Name soll von einer Werbeaktion kommen, die extra zahlte für ein Pik-Ass mit einem schwarzen Buben. In den 1960ern veröffentlichte der Mathematiker Thorp das Kartenzählen, und Blackjack wurde als schlagbares Casinospiel berühmt.",
 "r.classic.win": "Komm näher an 21 als der Dealer, ohne darüber zu gehen. Über 21 heißt „überkauft“ und verliert. Ass und Zehn als erste zwei Karten (Blackjack) zahlen 3:2.",
 "r.classic.cult": "Das beliebteste Tischspiel in Casinos weltweit — und eines der seltenen, bei denen Können zählt: Richtiges Spiel (Grundstrategie) hält den Hausvorteil klein.",
 "r.classic.facts": "10, J, Q, K zählen 10; ein Ass 1 oder 11|Der Dealer zieht bis 16 und steht ab 17|Du wählst: Karte, Stehen, Verdoppeln, Teilen",
 "r.classic.p": [
  {
   "t": "Karten zählen",
   "b": "2–9 zählen ihren Wert; 10, J, Q und K zählen alle 10.",
   "task": "Was ergeben K und 7?",
   "ok": "Richtig: K ist 10, also 10 + 7 = 17.",
   "ng": "J, Q und K zählen 10."
  },
  {
   "t": "Ein Ass ist 1 oder 11",
   "b": "Ein Ass zählt 1 oder 11, je nachdem, was hilft. Eine Hand, die ein Ass als 11 zählt, ist „soft“.",
   "task": "Was ergeben A und 6?",
   "ok": "Richtig — 7 oder 17, eine „Soft 17“. Sie kann sich mit einer weiteren Karte nicht überkaufen.",
   "ng": "Ein Ass kann 1 oder 11 sein."
  },
  {
   "t": "Blackjack",
   "b": "Ein Ass und eine Zehnerkarte (10, J, Q, K) als erste zwei Karten sind ein „Blackjack“ — die beste Hand. Er zahlt 3:2.",
   "task": "Du setzt $100 und hast Blackjack. Was gewinnst du?",
   "ok": "Richtig! 3:2 ist das 1,5-Fache: $150.",
   "ng": "Ein Blackjack zahlt 3:2 (das 1,5-Fache)."
  },
  {
   "t": "Überkauft",
   "b": "Über 21 ist „überkauft“ und verliert sofort, egal was der Dealer macht.",
   "task": "10 + 6 + 9 = 25. Diese Hand…",
   "ok": "Richtig: über 21 — überkauft, verloren.",
   "ng": "Über 21 verliert sofort."
  },
  {
   "t": "Die Dealerregel",
   "b": "Der Dealer hat keine Wahl: Er zieht bis 16 und steht ab 17.",
   "task": "Der Dealer hat K und 6 = 16. Was passiert?",
   "ok": "Richtig: 16 oder weniger, also muss der Dealer ziehen.",
   "ng": "Der Dealer zieht immer bis 16."
  },
  {
   "t": "Verdoppeln",
   "b": "Nach den ersten zwei Karten darfst du den Einsatz verdoppeln und bekommst genau eine Karte. Nutze es, wenn du vorne liegst.",
   "task": "6 + 5 = 11, der Dealer zeigt 6. Der beste Zug?",
   "ok": "Richtig! 11 ergibt oft 21, und die 6 des Dealers überkauft sich oft — perfekt zum Verdoppeln.",
   "ng": "11 gegen eine 6 ist der Moment zum Verdoppeln."
  },
  {
   "t": "Teilen",
   "b": "Zwei Karten gleichen Rangs kannst du in zwei Hände teilen, indem du denselben Einsatz noch einmal setzt.",
   "task": "8 und 8 (16) gegen eine 9 des Dealers. Was tust du?",
   "ok": "Richtig: 16 ist die schlechteste Hand — teile in zwei Hände ab 8.",
   "ng": "8er immer teilen."
  },
  {
   "t": "Versicherung",
   "b": "Zeigt der Dealer ein Ass, kannst du dich für den halben Einsatz gegen einen Blackjack versichern — auf Dauer eine Verlustwette.",
   "task": "Was zahlt die Versicherung?",
   "ok": "Richtig: 2:1. Die verdeckte Karte ist nur in etwa 30 % der Fälle eine Zehn, also meist nein.",
   "ng": "Die Versicherung zahlt 2:1."
  }
 ],
 "r.european.origin": "Europäische Casinos",
 "r.european.players": "1–7 Spieler + Dealer",
 "r.european.time": "ca. 1 Min. pro Runde",
 "r.european.hist": "Das übliche Spiel in Europa und Australien. Ohne verdeckte Karte ist Schummeln durch Hineinspähen schwerer.",
 "r.european.win": "Wie in Vegas, nur bekommt der Dealer zuerst eine Karte und zieht die zweite nach allen Spielern.",
 "r.european.cult": "Viele europäische Casinos erlauben Verdoppeln nur mit 9–11. Gegen Zehn oder Ass vorsichtig spielen.",
 "r.european.facts": "Keine verdeckte Karte beim Dealer|Ein Dealer-Blackjack nimmt auch verdoppelte und geteilte Einsätze|Verdoppeln mit 9–11, kein Aufgeben",
 "r.european.p": [
  {
   "t": "Keine verdeckte Karte",
   "b": "Der Dealer bekommt zuerst eine offene Karte und die zweite erst, wenn alle Spieler fertig sind.",
   "task": "Wann bekommt der Dealer die zweite Karte?",
   "ok": "Richtig — deshalb weißt du vor dem Verdoppeln nicht, ob er Blackjack hat.",
   "ng": "Die zweite Karte kommt nach den Spielern."
  },
  {
   "t": "Blackjack nimmt alles",
   "b": "Macht der Dealer dann einen Blackjack, verliert auch das zusätzliche Geld aus Verdoppeln und Teilen.",
   "task": "Du hast $100 verdoppelt und 20. Der Dealer dreht Zehn und Ass. Was verlierst du?",
   "ok": "Richtig: die ganzen $200. Darum gegen Zehn oder Ass weniger verdoppeln.",
   "ng": "Das verdoppelte Geld geht auch verloren."
  }
 ],
 "r.spanish.origin": "Spanischer Stil, amerikanische Casinos",
 "r.spanish.players": "1–7 Spieler + Dealer",
 "r.spanish.time": "ca. 1 Min. pro Runde",
 "r.spanish.hist": "Eine Blackjack-Variante nach dem Vorbild des spanischen Blatts (das keine 10er hat). In den 1990ern verbreitete sie sich in amerikanischen Casinos.",
 "r.spanish.win": "Gespielt ohne 10er, was dem Spieler schadet — dafür gewinnt eine 21 des Spielers immer, und 21 aus 5+ Karten oder 6-7-8 zahlen Boni.",
 "r.spanish.cult": "Verdoppeln mit beliebig vielen Karten, Ziehen auf geteilte Asse und weitere freundliche Regeln sorgen für lebhafte Hände.",
 "r.spanish.facts": "48 Karten pro Deck (die vier 10er raus)|21 und Blackjack des Spielers gewinnen immer|21 aus 5 Karten zahlt 3:2; Boni für 6-7-8 und 7-7-7",
 "r.spanish.p": [
  {
   "t": "Ein Deck ohne 10er",
   "b": "Jedes Deck verliert seine vier 10er (J, Q, K bleiben). Weniger Zehnerkarten sind etwas schlechter für den Spieler.",
   "task": "Wie viele Karten hat ein Deck?",
   "ok": "Richtig: 52 − 4 = 48.",
   "ng": "Die vier 10er gehen von 52 ab."
  },
  {
   "t": "21 gewinnt immer",
   "b": "Eine 21 des Spielers gewinnt sogar gegen eine 21 des Dealers (außer gegen einen Dealer-Blackjack).",
   "task": "Du hast 21 aus 5 Karten, der Dealer 21 aus 3. Das Ergebnis?",
   "ok": "Richtig! 21 gewinnt immer — und 21 aus 5 Karten zahlt einen 3:2-Bonus.",
   "ng": "In Spanish 21 gewinnt eine 21 des Spielers immer."
  },
  {
   "t": "Bonus-21",
   "b": "Eine 21 aus 6-7-8 oder 7-7-7 zahlt einen Bonus: 2:1 in einer Farbe, 3:1 in Pik.",
   "task": "6-7-8 in Kreuz. Was gewinnt ein Einsatz von $100?",
   "ok": "Richtig: 6-7-8 in einer Farbe zahlt 2:1 — $200.",
   "ng": "6-7-8 in einer Farbe zahlt 2:1."
  }
 ],
