 "r.free.time": "ca. 1 Min. pro Runde",
 "r.free.hist": "Ein neues Blackjack aus Las Vegas in den 2010ern. „Gratis verdoppeln und gratis teilen“ machte es beliebt, und es verbreitete sich weltweit.",
 "r.free.win": "Verdoppeln mit harten 9–11 und Teilen aller Paare außer Zehnern ist gratis: Das Casino legt einen „Gratis-Chip“ dazu, der wie Geld gewinnt, aber nie verloren geht.",
 "r.free.cult": "Dafür sind alle lebenden Hände unentschieden, wenn der Dealer bei 22 endet. Nutze jeden Gratis-Chip.",
 "r.free.facts": "Gratis verdoppeln mit harten 9, 10, 11|Gratis teilen aller Paare außer Zehnern|Eine 22 des Dealers ist unentschieden (Blackjacks gewinnen trotzdem)",
 "r.free.p": [
  {
   "t": "Gratis verdoppeln",
   "b": "Mit harten 9, 10 oder 11 übernimmt das Casino das Verdoppeln mit einem Gratis-Chip.",
   "task": "Du setzt $100 und hast 6 + 4 = 10. Was kostet das Verdoppeln?",
   "ok": "Richtig: nichts. Gewinne $200 oder verliere nur deine $100.",
   "ng": "Verdoppeln mit harten 9–11 ist gratis."
  },
  {
   "t": "Die 22 des Dealers",
   "b": "Dafür ist jede nicht überkaufte Hand unentschieden, wenn der Dealer bei genau 22 endet.",
   "task": "Du hast 18; der Dealer macht 10 + 6 + 6 = 22. Das Ergebnis?",
   "ok": "Richtig: normalerweise ein Sieg, aber bei Free Bet ist 22 unentschieden.",
   "ng": "Eine 22 des Dealers ist unentschieden."
  },
  {
   "t": "Gratis teilen",
   "b": "Alle Paare außer Zehnern können ohne zusätzliches Geld geteilt werden (Gratis-Chip).",
   "task": "8 und 8 gegen eine Zehn. Was tust du?",
   "ok": "Richtig! Zwei Hände gratis.",
   "ng": "Teilen aller Paare außer Zehnern ist gratis."
  }
 ],
