 "l.value": "Handwerte",
 "lp.value": "10, J, Q, K sind 10; ein Ass 1 oder 11",
 "ld.value": "Ein paar Karten schnell zusammenzählen.",
 "x.value": "2–9 zählen ihren Wert; 10, J, Q, K zählen 10.\nEin Ass zählt 11, außer du kämst damit über 21 — dann zählt es 1.",
 "ltip.value": "Zähl zuerst die Zehner — das geht schneller.",
 "l.soft": "Soft und hart",
 "lp.soft": "Hände, die ein Ass als 11 zählen können",
 "ld.soft": "Soft-Hände erkennen — sie werden ganz anders gespielt.",
 "x.soft": "Eine Hand, die ein Ass als 11 zählen kann, ohne über 21 zu gehen, ist „soft“ (A + 6 = Soft 17).\nEine Soft-Hand kann sich mit einer weiteren Karte nicht überkaufen. Eine Hand, deren Asse nur 1 sein können, ist „hart“.",
 "ltip.soft": "A + 6 + 10: Ein Ass als 11 ergäbe 27, also ist es harte 17.",
 "l.pay": "Auszahlungen",
 "lp.pay": "Sieg 1:1, Blackjack 3:2",
 "ld.pay": "Was Blackjack, Verdoppeln, Aufgeben und Versicherung zahlen.",
 "x.pay": "Ein normaler Sieg zahlt deinen Einsatz (1:1); ein Blackjack das 1,5-Fache (3:2); bei Unentschieden gibt es ihn zurück.\nEin gewonnenes Verdoppeln zahlt den doppelten Einsatz; Aufgeben verliert die Hälfte; Versicherung zahlt 2:1.",
 "ltip.pay": "An einem 6:5-Tisch zahlt ein Blackjack nur das 1,2-Fache.",
 "l.dealer": "Die Dealerregel",
 "lp.dealer": "Zieht bis 16, steht ab 17",
 "ld.dealer": "Sag, ob der Dealer zieht. Achte auf Soft 17.",
 "x.dealer": "Der Dealer hat keine Wahl: Er zieht bis 16 und steht ab 17.\nStehen bei Soft 17 (A + 6) ist S17, Ziehen ist H17 — der Filz sagt, was gilt.",
 "ltip.dealer": "Der Dealer überkauft sich in etwa 28 % der Fälle.",
 "l.hard": "Harte Hände",
 "lp.hard": "Karte, Stehen oder Verdoppeln mit 8–16",
 "ld.hard": "Die Grundstrategie für Hände ohne Ass, je nach offener Dealerkarte.",
 "x.hard": "Mit 11 oder weniger kannst du dich nicht überkaufen: Karte oder Verdoppeln. 11 ist ideal zum Verdoppeln.\nMit 12–16 grob: gegen eine schwache Dealerkarte (2–6) stehen, gegen eine starke (7–Ass) Karte.",
 "ltip.hard": "Im Zweifel zuerst fragen: Ist die Dealerkarte schwach (2–6) oder stark (7–Ass)?",
 "l.stiff": "Die Stiff-Hände",
 "lp.stiff": "12–16: Karte oder Stehen?",
 "ld.stiff": "Hände, die sich leicht überkaufen — die Dealerkarte entscheidet.",
 "x.stiff": "12–16 überkaufen sich leicht beim Ziehen und sind schwach beim Stehen.\nGegen einen schwachen Dealer (2–6) stehen und hoffen, dass er sich überkauft; gegen eine starke Karte (7–Ass) Karte. Ausnahme: 12 gegen 2 oder 3 Karte.",
 "ltip.stiff": "Schlechte Hände wie 16 gegen eine Zehn: aufgeben, wenn möglich — die Hälfte zurück ist das Beste.",
 "l.softs": "Soft-Hände",
 "lp.softs": "A+2 bis A+8 spielen",
 "ld.softs": "Wann man mit einer Hand angreift, die sich nicht überkaufen kann.",
 "x.softs": "Soft-Hände können sich mit einer Karte nicht überkaufen — zieh mit ihnen öfter als mit harten Händen.\nBei Soft 17 oder weniger nie stehen; gegen einen schwachen Dealer verdoppeln. Soft 18 hängt vom Dealer ab.",
 "ltip.softs": "Soft 18 (A+7) zieht gegen 9, Zehn oder Ass.",
 "l.pairs": "Paare teilen",
 "lp.pairs": "Asse und 8er teilen, nicht Zehner oder 5er",
 "ld.pairs": "Welche Paare man gegen welche Dealerkarten teilt.",
 "x.pairs": "Asse und 8er immer teilen. Zehner (20) und 5er (10) nie.\nDie anderen Paare meist gegen einen schwachen Dealer teilen.",
 "ltip.pairs": "Mit zwei 9ern (18) gegen 7, Zehn oder Ass stehen.",
 "l.insurance": "Versicherung",
 "lp.insurance": "Gegen das Ass des Dealers versichern",
 "ld.insurance": "Was Versicherung und Even Money wirklich wert sind.",
 "x.insurance": "Die Versicherung ist eine 2:1-Wette darauf, dass die verdeckte Karte eine Zehn ist.\nIn einem normalen Schuh passiert das in etwa 30 % der Fälle — weniger als ein Drittel (33 %), also verliert sie auf Dauer.",
 "ltip.insurance": "Zähler versichern nur ab einem True Count von +3.",
 "l.sidebets": "Nebenwetten",
 "lp.sidebets": "Perfect Pairs und 21+3",
 "ld.sidebets": "Nenne die Hand und ihre Auszahlung.",
 "x.sidebets": "Perfect Pairs: Deine ersten zwei Karten haben denselben Rang — gleiche Farbe 25:1, gleiche Kartenfarbe rot/schwarz 12:1, verschiedene 6:1.\n21+3: Deine zwei Karten und die offene Dealerkarte bilden eine Pokerhand — Flush 5:1, Straße 10:1, Drilling 30:1…",
 "ltip.sidebets": "Nebenwetten haben 3–6 % Hausvorteil oder mehr. Klein halten.",
 "l.variants": "Die Varianten",
 "lp.variants": "Europäisch, Spanish 21, Free Bet",
 "ld.variants": "Wie sich die vier Spiele unterscheiden und was das für dein Spiel heißt.",
 "x.variants": "Europäisch: keine verdeckte Karte; ein späterer Blackjack nimmt auch Verdopplungen.\nSpanish 21: keine 10er, aber 21 gewinnt immer und zahlt Boni. Free Bet: Gratis verdoppeln und teilen, eine 22 des Dealers ist unentschieden.",
 "ltip.variants": "Andere Regeln, andere Tabelle — vergleiche sie unter Lernen.",
 "l.edge": "Hausvorteil",
 "lp.edge": "Was die Regeln wert sind",
 "ld.edge": "S17 vs. H17, 3:2 vs. 6:5, Decks… die Kosten jeder Regel.",
 "x.edge": "Der Hausvorteil ist der Anteil deiner Einsätze, den du auf Dauer verlierst — mit Grundstrategie etwa 0,5 %.\n6:5 kostet etwa 1,4 %, H17 etwa 0,2 %; weniger Decks helfen ein wenig.",
 "ltip.edge": "Nach Gefühl statt nach Grundstrategie zu spielen treibt den Vorteil auf mehrere Prozent.",
 "l.hilo": "Hi-Lo-Werte",
 "lp.hilo": "2–6 sind +1, Zehner und Asse −1",
 "ld.hilo": "Nenne sofort den Zählwert jeder Karte.",
 "x.hilo": "Hi-Lo: niedrige Karten (2–6) sind +1, 7–9 sind 0, hohe Karten (10, J, Q, K, A) sind −1.\nJe mehr niedrige Karten weg sind, desto mehr Zehner und Asse sind übrig — gut für den Spieler.",
 "ltip.hilo": "Ein ganzes Deck ergibt genau 0.",
 "l.running": "Running Count",
 "lp.running": "Die gesehenen Karten zusammenzählen",
 "ld.running": "Zähle die Werte mehrerer Karten zusammen.",
 "x.running": "Der Running Count ist die Summe der Hi-Lo-Werte aller Karten seit dem Mischen.\nEin Plus und ein Minus heben sich auf — zähle paarweise, das geht schneller.",
 "ltip.running": "Schalte „Zählstand anzeigen“ in den Optionen aus, um am Tisch zu üben.",
 "l.truec": "True Count",
 "lp.truec": "Running ÷ verbleibende Decks",
 "ld.truec": "Teile durch die verbleibenden Decks, um den echten Vorteil zu sehen.",
 "x.truec": "Ein Running Count von +6 bedeutet bei 6 restlichen Decks etwas anderes als bei 1.\nTrue Count = Running Count ÷ verbleibende Decks. Jedes +1 True Count bringt dem Spieler etwa +0,5 %.",
 "ltip.truec": "Bei etwa +1 liegt der Vorteil nahe null; darüber liegt der Spieler vorn.",
 "l.bankroll": "Einsätze und Geld",
 "lp.bankroll": "1–5 % der Chips pro Einsatz",
 "ld.bankroll": "Einsatzideen und ihre Grenzen.",
 "x.bankroll": "Blackjack schwankt stark, und Verdoppeln und Teilen können deinen Einsatz erhöhen.\nEinsatzsysteme wie die Martingale ändern den Hausvorteil nicht — nur deine Spielweise (und das Zählen) tun das.",
 "ltip.bankroll": "Leg dein Stop-Loss vor dem Start fest.",
