 "e.hard": "Kein Ass: harte {n}.",
 "e.hardA": "Ein Ass als 11 ginge über 21, also ist das Ass 1: harte {n}.",
 "q.pay.bj": "Du setzt {b} und hast Blackjack (der Dealer nicht). Dein Ergebnis?",
 "q.pay.win": "Du setzt {b} und gewinnst normal. Dein Ergebnis?",
