 "o.fixed.classic": "हमेशा: ऊपर इक्का या दहाई होने पर डीलर छिपा पत्ता जाँचता है। किन्हीं भी दो पत्तों पर डबल, 4 हाथों तक स्प्लिट, स्प्लिट इक्कों को एक-एक पत्ता। इंश्योरेंस 2:1 देता है।",
 "o.fixed.european": "हमेशा: कोई छिपा पत्ता नहीं (जाँच नहीं)। 9–11 पर डबल, 2 हाथों तक स्प्लिट, सरेंडर नहीं। इंश्योरेंस 2:1 देता है।",
 "o.fixed.spanish": "हमेशा: 48 पत्तों के डेक (10 के बिना)। कितने भी पत्तों पर डबल; स्प्लिट इक्कों पर हिट और दोबारा स्प्लिट हो सकता है। खिलाड़ी का 21 और ब्लैकजैक हमेशा जीतते हैं। बोनस: 5 पत्तों का 21 3:2, 6 पत्ते 2:1, 7+ पत्ते 3:1, 6-7-8 / 7-7-7 3:2 (एक ही सूट 2:1, हुकुम 3:1)।",
 "o.fixed.free": "हमेशा: हार्ड 9–11 पर डबल और दहाई छोड़कर हर जोड़ी का स्प्लिट मुफ़्त है (फ़्री चिप कभी नहीं हारती)। डीलर 22 पर रुके तो हर बचा हुआ हाथ पुश होता है (ब्लैकजैक फिर भी जीतता है)।",
 "o.carry": "आपकी चिप्स अगले गेम में साथ जाती हैं। शून्य होने पर आप {s} से फिर शुरू करेंगे।",
 "o.note": "न्यूनतम दाँव 25 (अधिकतम 10,000)। चिप्स: 25, 100, 500, 1,000, 5,000। कट कार्ड निकलने पर उस राउंड के बाद शू खत्म हो जाता है।",
