 "ck.doneBad": "{n} फ़ैसले बेसिक स्ट्रैटेजी से अलग थे। नतीजा जो भी हो, लंबे समय में इनका नुकसान होता है।",
 "ck.doneWin": "सब कुछ बेसिक स्ट्रैटेजी से। जीत में थोड़ी किस्मत थी, पर खेल बिल्कुल सही था।",
 "ck.doneLose": "सब कुछ बेसिक स्ट्रैटेजी से। हार किस्मत की थी — खेल सही था।",
 "ck.donePush": "सब कुछ बेसिक स्ट्रैटेजी से। पुश।",
 "ck.avgLoss": "इस दाँव का औसत नुकसान (प्रति राउंड)",
 "why.pA": "इक्कों को हमेशा स्प्लिट करें: 11 से शुरू होने वाले दो हाथ बहुत मज़बूत होते हैं।",
 "why.p8": "8 की जोड़ी 16 है, सबसे खराब हाथ। इसे 8 से शुरू होने वाले दो हाथों में स्प्लिट करें।",
 "why.pWeak": "डीलर का {u} कमज़ोर है और अक्सर बस्ट होता है — टेबल पर ज़्यादा पैसा लगाने के लिए स्प्लिट करें।",
 "why.p": "यह जोड़ी दो अलग हाथों के रूप में बेहतर करती है।",
 "why.p10": "20 बहुत मज़बूत हाथ है। स्टैंड करें — स्प्लिट न करें।",
 "why.p5": "5 की जोड़ी 10 है: स्प्लिट की बजाय डबल करें।",
 "why.R": "डीलर के {u} के सामने यह हाथ 25% से कम बार जीतता है। आधा छोड़ देना सबसे सस्ता रास्ता है।",
 "why.Dsoft": "सॉफ्ट हाथ एक पत्ते से बस्ट नहीं हो सकता, और डीलर का {u} कमज़ोर है — दाँव डबल करें।",
 "why.D11": "11 सबसे अच्छा डबल है: एक पत्ता अक्सर 21 बना देता है।",
 "why.D": "एक और पत्ता अक्सर मज़बूत हाथ बनाता है, और आप डीलर के {u} से आगे हैं। डबल करें।",
 "why.softS": "सॉफ्ट {t} काफ़ी मज़बूत है। स्टैंड करें।",
 "why.softH": "सॉफ्ट हाथ एक पत्ते से बस्ट नहीं हो सकता। डीलर के {u} को हराने के लिए हिट करें।",
 "why.h17": "17 या ज़्यादा पर हिट करने से बहुत बार बस्ट होंगे। स्टैंड करें।",
 "why.stiffS": "डीलर का {u} अक्सर बस्ट होता है। बस्ट होने का जोखिम न लें — डीलर को बस्ट होने दें।",
 "why.stiffS2": "{t} अक्सर बस्ट होता है और रुकने पर कमज़ोर है — पर यहाँ स्टैंड करने से थोड़ा कम नुकसान है।",
 "why.stiffH": "डीलर का {u} मज़बूत है (17+ बनने की संभावना)। रुकने पर {t} हारता है, इसलिए हिट करें।",
 "why.stiffH2": "{t} अभी भी काफ़ी सुरक्षित रूप से पत्ता ले सकता है। हिट करें।",
 "why.low": "{t} बस्ट नहीं हो सकता। हिट करें।",
 "gr.main": "{k}: हाउस एज {e} (बेसिक स्ट्रैटेजी के साथ) — कैसीनो के सबसे सस्ते दाँवों में से एक।",
