 "tips.h": "टिप्स",
 "tips.more": "और टिप्स ({n})",
 "tips.less": "कम",
 "tip.luck": "अब तक आपका अपेक्षित नुकसान लगभग {e} है; आपका कुल {n} है। यह अंतर किस्मत है — राउंड बढ़ने पर यह घटता है।",
 "tip.bot": "{n} हर हार के बाद दाँव दोगुना करता है (अभी {a})। मार्टिंगेल हाउस एज नहीं बदलता — बस कभी-कभार होने वाले बड़े नुकसान को और बड़ा कर देता है।",
 "tipg.1": "बेसिक स्ट्रैटेजी से खेलने पर हाउस एज लगभग 0.5% रह जाता है — कैसीनो के सबसे सस्ते खेलों में से एक।",
 "tipg.2": "डीलर का 2–6 “अक्सर बस्ट होता है”, 7–इक्का “मज़बूत” है। शक हो तो पहले डीलर का पत्ता देखें।",
 "tipg.3": "12–16 “स्टिफ़” हाथ हैं: डीलर के मज़बूत पत्ते पर हिट, कमज़ोर पर स्टैंड।",
 "tipg.4": "11 सबसे अच्छा डबल है। 10 पर भी डबल करें, सिवाय दहाई या इक्के के सामने।",
 "tipg.5": "इक्कों और 8 को हमेशा स्प्लिट करें; दहाई या 5 को कभी नहीं — बेसिक स्ट्रैटेजी का मूलमंत्र।",
 "tipg.6": "इंश्योरेंस तभी फ़ायदेमंद है जब बचे पत्तों में तीन में से एक से ज़्यादा दहाई हों। सामान्य शू में यह लगभग 30% है, इसलिए मना करें।",
 "tipg.7": "डीलर की तरह खेलने (17 तक हिट) से हाउस को लगभग 5.5% मिलता है — बेसिक स्ट्रैटेजी के एज का दस गुना से ज़्यादा (अध्ययन देखें)।",
 "tipg.8": "“कभी बस्ट नहीं” (हर 12+ पर स्टैंड) से भी लगभग 4–6% नुकसान होता है। कभी स्टैंड करना होता है, कभी हिट।",
 "tipg.9": "सॉफ्ट हाथ (इक्का 11 गिना) एक पत्ते से बस्ट नहीं हो सकता। सॉफ्ट 17 या कम पर हिट या डबल करें।",
 "tipg.10": "6:5 ब्लैकजैक टेबल 3:2 से लगभग 1.4% महँगी है। टेबल पर लिखा नियम देखें।",
 "tipg.11": "सॉफ्ट 17 पर हिट करने वाला डीलर (H17) S17 के मुकाबले आपको लगभग 0.2% महँगा पड़ता है।",
 "tipg.12": "Hi-Lo: 2–6 = +1, 7–9 = 0, दहाई और इक्के = −1। काउंट जितना ऊँचा, उतने ज़्यादा दहाई और इक्के बचे — आपके लिए अच्छा।",
 "tipg.13": "ट्रू काउंट = रनिंग काउंट ÷ बचे डेक। ट्रू काउंट का हर +1 खिलाड़ी को लगभग +0.5% देता है।",
 "tipg.14": "कार्ड काउंटिंग गैरकानूनी नहीं है, पर कैसीनो इसे पसंद नहीं करते। यहाँ यह खेल को समझने का तरीका है।",
 "tipg.15": "सैम कार्ड काउंट करता है: वह काउंट ऊँचा होने पर ही बड़ा दाँव लगाता है। उसके दाँव देखें।",
 "tipg.16": "लिन एक जैसे दाँव के साथ बेसिक स्ट्रैटेजी खेलती है, आइको “कभी बस्ट नहीं होती”, मार्को मार्टिंगेल खेलता है। समय के साथ फ़र्क दिखता है।",
 "tipg.17": "बहुत खराब हाथों पर सरेंडर आधा बचाता है (हार्ड 16 बनाम 9, दहाई, इक्का; 15 बनाम दहाई)। कम होता है, पर ज़रूरी है।",
 "tipg.18": "साइड बेट पर हाउस एज 3–6% या ज़्यादा होता है — मुख्य दाँव से कहीं महँगा।",
 "tipg.19": "लगातार हार अगले पत्ते को नहीं बदलती (काउंट के अलावा)। वापस जीतने के लिए दाँव न बढ़ाएँ।",
 "tipg.20": "शुरू करने से पहले स्टॉप-लॉस तय करें — सबसे कारगर मनी मैनेजमेंट।",
 "tipv.classic": "वेगास स्ट्रिप: डीलर सॉफ्ट 17 पर स्टैंड करता है (बदला जा सकता है), सरेंडर की अनुमति — बेसिक स्ट्रैटेजी का मानक खेल।",
 "tipv.european": "यूरोपीय: डीलर की दहाई या इक्के के सामने कम डबल और स्प्लिट करें — डीलर का ब्लैकजैक अतिरिक्त पैसा भी ले जाता है।",
 "tipv.spanish": "स्पैनिश 21: दहाई कम होने से सामान्य ब्लैकजैक की तुलना में कम डबल और स्प्लिट करें।",
 "tipv.free": "फ़्री बेट: मुफ़्त डबल और स्प्लिट हमेशा लें — ये डीलर के 22 पुश का नुकसान वापस दिलाते हैं।",
