 "x.sidebets": "Perfect Pairs: आपके पहले दो पत्ते एक ही रैंक के — एक ही सूट 25:1, एक ही रंग 12:1, अलग रंग 6:1।\n21+3: आपके दो पत्ते और डीलर का खुला पत्ता पोकर हाथ बनाते हैं — फ़्लश 5:1, स्ट्रेट 10:1, थ्री ऑफ़ अ काइंड 30:1…",
