 "x.edge": "हाउस एज आपके दाँवों का वह हिस्सा है जो आप लंबे समय में हारते हैं — बेसिक स्ट्रैटेजी से लगभग 0.5%।\n6:5 से लगभग 1.4%, H17 से लगभग 0.2% नुकसान; कम डेक थोड़ी मदद करते हैं।",
