 "ld.hilo": "हर पत्ते की काउंट वैल्यू तुरंत बताएँ।",
 "x.hilo": "Hi-Lo: छोटे पत्ते (2–6) +1, 7–9 0, बड़े पत्ते (10, J, Q, K, A) −1।\nजितने ज़्यादा छोटे पत्ते निकल चुके, उतने ज़्यादा दहाई और इक्के बचे — खिलाड़ी के लिए अच्छा।",
 "ltip.hilo": "पूरे डेक का जोड़ ठीक 0 होता है।",
 "l.running": "रनिंग काउंट",
 "lp.running": "देखे गए पत्तों का जोड़",
 "ld.running": "कई पत्तों की काउंट वैल्यू जोड़ें।",
 "x.running": "रनिंग काउंट फ़ेंटने के बाद से हर पत्ते की Hi-Lo वैल्यू का जोड़ है।\nएक प्लस और एक माइनस कट जाते हैं — तेज़ी के लिए जोड़ियों में गिनें।",
 "ltip.running": "टेबल पर अभ्यास के लिए सेटिंग्स में “काउंट दिखाएँ” बंद करें।",
 "l.truec": "ट्रू काउंट",
 "lp.truec": "रनिंग ÷ बचे डेक",
 "ld.truec": "असली एज देखने के लिए बचे डेक से भाग दें।",
 "x.truec": "+6 का रनिंग काउंट 6 बचे डेक पर कुछ और मतलब रखता है और 1 पर कुछ और।\nट्रू काउंट = रनिंग काउंट ÷ बचे डेक। ट्रू काउंट का हर +1 खिलाड़ी को लगभग +0.5% देता है।",
 "ltip.truec": "लगभग +1 पर एज शून्य के करीब होता है; उससे ऊपर खिलाड़ी आगे होता है।",
 "l.bankroll": "दाँव और पैसा",
 "lp.bankroll": "हर दाँव पर चिप्स का 1–5%",
 "ld.bankroll": "दाँव लगाने के तरीके और उनकी सीमाएँ।",
 "x.bankroll": "ब्लैकजैक में उतार-चढ़ाव बहुत होता है, और डबल व स्प्लिट आपका दाँव बढ़ा सकते हैं।\nमार्टिंगेल जैसे सिस्टम हाउस एज नहीं बदलते — सिर्फ़ आपके खेलने का तरीका (और काउंट) बदलता है।",
 "ltip.bankroll": "शुरू करने से पहले स्टॉप-लॉस तय करें।",
