 "tips.h": "نصائح",
 "tips.more": "نصائح أكثر ({n})",
 "tips.less": "أقل",
 "tip.luck": "خسارتك المتوقعة حتى الآن نحو {e}؛ وصافيك {n}. الفرق هو الحظ — ويتقلّص مع تراكم الجولات.",
 "tip.bot": "{n} يضاعف الرهان بعد كل خسارة (الآن {a}). نظام مارتينغال لا يغيّر ميزة الكازينو — بل يجعل الخسارة الكبيرة النادرة أكبر.",
 "tipg.1": "اللعب بالاستراتيجية الأساسية يخفض ميزة الكازينو إلى نحو 0.5% — من أرخص ألعاب الكازينو.",
 "tipg.2": "ورقة 2–6 لدى الموزّع «كثيرة التجاوز»، و7–آس «قوية». عند الشك، انظر إلى ورقة الموزّع أولًا.",
 "tipg.3": "12–16 أيدٍ «حرجة»: اسحب أمام ورقة قوية للموزّع، وقف أمام ورقة ضعيفة.",
 "tipg.4": "11 أفضل مضاعفة. و10 تُضاعف أيضًا، إلا أمام عشرة أو آس.",
 "tipg.5": "قسّم الآسات والثمانيات دائمًا؛ ولا تقسّم العشرات أو الخمسات أبدًا — شعار الاستراتيجية الأساسية.",
 "tipg.6": "التأمين لا يربح إلا إذا كانت أكثر من ورقة من كل ثلاث متبقية عشرة. في حذاء عادي النسبة نحو 30%، فقل لا.",
 "tipg.7": "اللعب مثل الموزّع (السحب حتى 17) يعطي الكازينو نحو 5.5% — أكثر من عشرة أضعاف ميزته مع الاستراتيجية الأساسية (انظر دراسة).",
 "tipg.8": "«لا تتجاوز أبدًا» (الوقوف على أي 12+) يكلّف أيضًا نحو 4–6%. هناك وقت للوقوف ووقت للسحب.",
 "tipg.9": "اليد الليّنة (آس يُحسب 11) لا تتجاوز بورقة واحدة. اسحب أو ضاعف على 17 ليّنة وما دونها.",
 "tipg.10": "طاولة بلاك جاك 6:5 تكلّف نحو 1.4% أكثر من 3:2. تحقّق من المكتوب على الطاولة.",
 "tipg.11": "الموزّع الذي يسحب على 17 ليّنة (H17) يكلّفك نحو 0.2% مقارنة بـ S17.",
 "tipg.12": "Hi-Lo: 2–6 = +1، 7–9 = 0، العشرات والآسات = −1. كلما ارتفع العدّ بقي عشرات وآسات أكثر — وهذا جيد لك.",
 "tipg.13": "العدّ الحقيقي = العدّ الجاري ÷ الرزم المتبقية. كل +1 في العدّ الحقيقي يساوي نحو +0.5% للاعب.",
 "tipg.14": "عدّ الأوراق ليس مخالفًا للقانون، لكن الكازينوهات لا تحبه. هنا هو وسيلة لفهم كيف تعمل اللعبة.",
 "tipg.15": "سام يعدّ الأوراق: لا يراهن بكثير إلا عندما يكون العدّ مرتفعًا. راقب رهاناته.",
 "tipg.16": "لين تلعب بالاستراتيجية الأساسية برهان ثابت، وأيكو «لا تتجاوز أبدًا»، وماركو يلعب مارتينغال. مع الوقت يظهر الفرق.",
 "tipg.17": "الاستسلام يوفّر النصف في الأيدي السيئة جدًا (16 صلبة أمام 9 أو عشرة أو آس؛ 15 أمام عشرة). نادر لكنه مهم.",
 "tipg.18": "الرهانات الجانبية بميزة كازينو 3–6% أو أكثر — أغلى بكثير من الرهان الرئيسي.",
 "tipg.19": "سلسلة الخسائر لا تغيّر الورقة التالية (إلا عبر العدّ). لا ترفع رهانك لتستعيد ما خسرت.",
 "tipg.20": "حدّد حد الخسارة قبل أن تبدأ — أنجح إدارة للمال.",
 "tipv.classic": "فيغاس ستريب: يقف الموزّع على 17 ليّنة (قابل للتغيير)، والاستسلام مسموح — اللعبة القياسية وراء الاستراتيجية الأساسية.",
 "tipv.european": "الأوروبية: أمام عشرة أو آس لدى الموزّع، ضاعف وقسّم أقل — فبلاك جاك الموزّع يأخذ المال الإضافي أيضًا.",
 "tipv.spanish": "سبانيش 21: مع قلّة العشرات، ضاعف وقسّم أقل مما في البلاك جاك العادي.",
 "tipv.free": "فري بِت: خذ دائمًا المضاعفات والتقسيمات المجانية — فهي تعوّض ما يأخذه تعادل 22 الموزّع.",
