 "r.classic.origin": "فرنسا، القرن الثامن عشر (Vingt-et-un)",
 "r.classic.players": "1–7 لاعبين + الموزّع",
 "r.classic.time": "نحو دقيقة للجولة",
 "r.classic.hist": "يعود البلاك جاك إلى اللعبة الفرنسية «Vingt-et-un» (واحد وعشرون) وانتشر في أمريكا. يُقال إن الاسم جاء من عرض ترويجي كان يدفع أكثر لآس البستوني مع شاب أسود. في الستينيات نشر عالم الرياضيات ثورب طريقة عدّ الأوراق، فاشتهر البلاك جاك كلعبة كازينو يمكن التغلّب عليها.",
 "r.classic.win": "اقترب من 21 أكثر من الموزّع دون أن تتجاوزه. تجاوز 21 يُسمّى «تجاوزًا» وهو خسارة. آس وعشرة كأول ورقتين (بلاك جاك) يدفعان 3:2.",
 "r.classic.cult": "أشهر لعبة طاولة في كازينوهات العالم — ومن الألعاب النادرة التي تهمّ فيها المهارة: اللعب الصحيح (الاستراتيجية الأساسية) يُبقي ميزة الكازينو صغيرة.",
 "r.classic.facts": "10 وJ وQ وK تُحسب 10؛ والآس 1 أو 11|يسحب الموزّع على 16 وما دون ويقف على 17+|أنت تختار: سحب، وقوف، مضاعفة، تقسيم",
