 "r.classic.time": "около 1 мин на раунд",
 "r.classic.hist": "Блэкджек происходит от французской игры «Vingt-et-un» («двадцать одно») и распространился в Америке. Название, говорят, пошло от акции, где доплачивали за туз пик с чёрным валетом. В 1960-х математик Торп опубликовал метод подсчёта карт, и блэкджек прославился как казино-игра, которую можно обыграть.",
 "r.classic.win": "Наберите ближе к 21, чем дилер, но не больше. Больше 21 — «перебор» и проигрыш. Туз и десятка первыми двумя картами (блэкджек) платят 3:2.",
 "r.classic.cult": "Самая популярная настольная игра в казино мира — и редкая, где важно мастерство: правильная игра (базовая стратегия) держит преимущество казино маленьким.",
 "r.classic.facts": "10, J, Q, K — по 10; туз — 1 или 11|Дилер берёт при 16 и меньше, стоит на 17+|Ваш выбор: ещё, хватит, удвоить, сплит",
