   "b": "После первых двух карт можно удвоить ставку и взять ровно одну карту. Делайте это, когда вы впереди.",
   "task": "6 + 5 = 11, у дилера 6. Лучший ход?",
   "ok": "Верно! 11 часто даёт 21, а дилер с 6 часто перебирает — идеальное удвоение.",
   "ng": "11 против 6 — время удваивать."
