   "b": "Две карты одного достоинства можно разделить на две руки, добавив такую же ставку.",
   "task": "8 и 8 (16) против 9 у дилера. Что делать?",
   "ok": "Верно: 16 — худшая рука; делите на две руки, начинающиеся с 8.",
   "ng": "Восьмёрки всегда делят."
