 "vg.classic": "Стандартная игра Лас-Вегаса: 6 колод, дилер стоит на мягких 17, удвоения, сплиты и сдача. Начните отсюда.",
 "vg.european": "Дилер берёт только одну карту, а вторую — после игроков; блэкджек дилера забирает и удвоенные, и сплит-ставки. Удвоение только на 9–11.",
 "vg.spanish": "Играют без десяток. Зато 21 игрока всегда выигрывает, 21 из 5 карт и 6-7-8 платят бонусы, а удваивать можно на любом числе карт.",
 "vg.free": "Удвоения на 9–11 и сплиты всех пар, кроме десяток, бесплатны (бесплатные фишки). Взамен 22 у дилера — ничья.",
