 "o.surr": "Сдача",
 "o.surr.h": "Отказаться от первых двух карт и вернуть половину ставки.",
 "o.bj": "Выплата за блэкджек",
 "o.bj.h": "3:2 — настоящая выплата. Столы 6:5 хуже.",
 "o.das": "Удвоение после сплита",
 "o.das.h": "Разделённые руки тоже можно удваивать.",
 "o.side": "Побочные ставки",
 "o.side.h": "Показывать поля Perfect Pairs и 21+3.",
 "o.decks": "Колоды",
 "o.decks.h": "Сколько колод в шузе. Меньше колод — чуть лучше для игрока.",
 "o.deckN": "{n} кол.",
 "o.fixed.classic": "Всегда: дилер проверяет закрытую карту при открытом тузе или десятке. Удвоение на любых двух картах, сплит до 4 рук, разделённые тузы получают по одной карте. Страховка платит 2:1.",
 "o.fixed.european": "Всегда: нет закрытой карты (без проверки). Удвоение на 9–11, сплит до 2 рук, без сдачи. Страховка платит 2:1.",
 "o.fixed.spanish": "Всегда: колоды по 48 карт (без десяток). Удвоение на любом числе карт; к разделённым тузам можно добирать и снова делить. 21 и блэкджек игрока всегда выигрывают. Бонусы: 21 из 5 карт 3:2, из 6 карт 2:1, из 7+ карт 3:1, 6-7-8 / 7-7-7 3:2 (одной масти 2:1, пики 3:1).",
 "o.fixed.free": "Всегда: удвоения на жёстких 9–11 и сплиты всех пар, кроме десяток, бесплатны (бесплатная фишка не теряется). Когда дилер останавливается на 22, все живые руки — ничья (блэкджеки всё равно выигрывают).",
