 "sk.none": "ничего",
 "tips.h": "Советы",
 "tips.more": "Ещё советы ({n})",
 "tips.less": "Свернуть",
 "tip.luck": "Ваш ожидаемый проигрыш пока около {e}; итог — {n}. Разница — удача; с ростом числа раундов она уменьшается.",
 "tip.bot": "{n} удваивает ставку после каждого проигрыша (сейчас {a}). Мартингейл не меняет преимущество казино — он лишь делает редкий крупный проигрыш ещё крупнее.",
 "tipg.1": "Базовая стратегия снижает преимущество казино примерно до 0,5% — одна из самых дешёвых игр в казино.",
 "tipg.2": "У дилера 2–6 «часто перебирают», 7–туз — «сильные». Если сомневаетесь, сначала смотрите на карту дилера.",
 "tipg.3": "12–16 — «трудные» руки: берите против сильной карты дилера, стойте против слабой.",
 "tipg.4": "11 — лучшее удвоение. 10 тоже удваивают, кроме как против десятки или туза.",
 "tipg.5": "Тузы и восьмёрки делите всегда; десятки и пятёрки — никогда. Девиз базовой стратегии.",
 "tipg.6": "Страховка окупается, только когда больше трети оставшихся карт — десятки. В обычном шузе это около 30%, так что отказывайтесь.",
 "tipg.7": "Игра как у дилера (брать до 17) даёт казино около 5,5% — в десять с лишним раз больше, чем при базовой стратегии (см. «Анализ»).",
 "tipg.8": "«Без перебора» (стоять на любых 12+) тоже стоит около 4–6%. Есть время стоять и время брать.",
 "tipg.9": "Мягкая рука (туз за 11) не переберёт с одной картой. С мягкими 17 и ниже берите или удваивайте.",
 "tipg.10": "Стол с блэкджеком 6:5 стоит примерно на 1,4% дороже, чем 3:2. Смотрите надпись на сукне.",
 "tipg.11": "Дилер, берущий на мягких 17 (H17), стоит вам около 0,2% по сравнению с S17.",
 "tipg.12": "Hi-Lo: 2–6 = +1, 7–9 = 0, десятки и тузы = −1. Чем выше счёт, тем больше осталось десяток и тузов — это выгодно вам.",
 "tipg.13": "Истинный счёт = текущий счёт ÷ оставшиеся колоды. Каждый +1 истинного счёта даёт игроку около +0,5%.",
 "tipg.14": "Подсчёт карт не запрещён законом, но казино его не любят. Здесь это способ понять, как устроена игра.",
 "tipg.15": "Sam считает карты: он ставит много, только когда счёт высокий. Следите за его ставками.",
 "tipg.16": "Lin играет по базовой стратегии с ровными ставками, Aiko — «без перебора», Marco — по Мартингейлу. Со временем разница становится видна.",
 "tipg.17": "Сдача спасает половину на очень плохих руках (жёсткие 16 против 9, десятки, туза; 15 против десятки). Редко, но важно.",
 "tipg.18": "У побочных ставок преимущество казино 3–6% и больше — намного дороже основной ставки.",
 "tipg.19": "Серия проигрышей не меняет следующую карту (кроме как через счёт). Не поднимайте ставку, чтобы отыграться.",
 "tipg.20": "Решите лимит проигрыша до начала игры — это лучшее управление деньгами.",
 "tipv.classic": "Vegas Strip: дилер стоит на мягких 17 (можно изменить), сдача разрешена — стандартная игра, на которой построена базовая стратегия.",
 "tipv.european": "European: против десятки или туза дилера удваивайте и делите реже — блэкджек дилера забирает и доплату.",
 "tipv.spanish": "Spanish 21: с меньшим числом десяток удваивайте и делите реже, чем в обычном блэкджеке.",
 "tipv.free": "Free Bet: всегда используйте бесплатные удвоения и сплиты — они возвращают то, что забирает ничья на 22 дилера.",
