Object.assign(I18N.zh, {"fl.h": "局面变了 — 重新判断", "fl.hit": "{a} 时要牌 → 拿到 {c}，现在 {b}。", "fl.split": "分牌后的这手：拿到 {c}，现在 {b}。", "fl.bust": "下一张爆牌概率", "fl.ev": "这手的期望值（要牌前 → 现在）", "fl.weak": "弱牌（容易爆）", "fl.strong": "强牌（容易到17以上）", "fl.21": "21点，不可能更好了，停牌。", "fl.soft": "仍是软{b}：A可以改算1，再要一张也不会爆。不够强就继续要。", "fl.softHard": "A算11会爆，所以现在算1。把它当作会爆的“硬{b}”重新考虑。", "fl.h17": "现在是 {b}。17以上要牌太容易爆，基本应停牌。", "fl.stiff": "进入12–16：再要牌可能爆。关键是庄家明牌 {u}，{w}。", "fl.stiff2": "仍是 {b}。和之前一样，看庄家的 {u}（{w}）决定要牌还是停牌。", "fl.low": "{b} 再要牌也不会爆。再要一张让牌更强。"});
Object.assign(I18N.ko, {"fl.h": "상황이 바뀌었습니다 — 다시 판단하기", "fl.hit": "{a}에서 히트 → {c}를 받아 {b}.", "fl.split": "스플릿 후 이 핸드: {c}를 받아 {b}.", "fl.bust": "다음 카드로 버스트", "fl.ev": "이 핸드의 기대값 (전 → 지금)", "fl.weak": "약한 카드(버스트하기 쉬움)", "fl.strong": "강한 카드(17 이상 되기 쉬움)", "fl.21": "21입니다. 더 좋아질 수 없으니 스탠드.", "fl.soft": "아직 소프트 {b}. A를 1로 되돌릴 수 있어 한 장 더 받아도 버스트하지 않습니다.", "fl.softHard": "A를 11로 세면 버스트하므로 이제 1입니다. 버스트할 수 있는 \"하드 {b}\"로 다시 생각합니다.", "fl.h17": "{b}가 되었습니다. 17 이상은 히트하면 버스트하기 쉬우니 스탠드가 기본입니다.", "fl.stiff": "12~16이 되었습니다. 히트하면 버스트할 수 있습니다. 판단 기준은 딜러의 {u}, {w}.", "fl.stiff2": "아직 {b}. 앞과 같이 딜러의 {u}({w})를 보고 히트/스탠드를 정합니다.", "fl.low": "{b}는 아직 버스트하지 않는 합계. 한 장 더 받아 강하게 만드세요."});
Object.assign(I18N.es, {"fl.h": "La jugada ha cambiado — piénsalo de nuevo", "fl.hit": "Pediste con {a} → salió {c}, ahora {b}.", "fl.split": "Esta mano tras separar: recibió {c}, ahora {b}.", "fl.bust": "Pasarse con la próxima carta", "fl.ev": "Valor de esta mano (antes → ahora)", "fl.weak": "una carta débil (se pasa a menudo)", "fl.strong": "una carta fuerte (suele llegar a 17+)", "fl.21": "21: no puede mejorar. Plántate.", "fl.soft": "Sigue siendo blanda {b}: el as puede volver a valer 1, así que otra carta no te pasa.", "fl.softHard": "Contar el as como 11 te pasaría, así que ahora vale 1. Piénsala como una dura {b}, que sí puede pasarse.", "fl.h17": "Ahora {b}. Con 17 o más, pedir te pasa demasiado: lo normal es plantarse.", "fl.stiff": "Estás en 12–16: pedir puede pasarte. Decide la carta del crupier: {u}, {w}.", "fl.stiff2": "Sigue en {b}. Como antes, el {u} del crupier ({w}) decide si pides o te plantas.", "fl.low": "{b} aún no puede pasarse. Pide otra para mejorarla."});
Object.assign(I18N.fr, {"fl.h": "La situation a changé — réfléchissez à nouveau", "fl.hit": "Carte sur {a} → {c}, maintenant {b}.", "fl.split": "Cette main après le partage : reçu {c}, maintenant {b}.", "fl.bust": "Sauter à la prochaine carte", "fl.ev": "Valeur de la main (avant → maintenant)", "fl.weak": "une carte faible (saute souvent)", "fl.strong": "une carte forte (fait souvent 17+)", "fl.21": "21 : impossible de faire mieux. Restez.", "fl.soft": "Toujours souple {b} : l'as peut redevenir 1, une carte de plus ne vous fait pas sauter.", "fl.softHard": "Compter l'as 11 vous ferait sauter : il vaut maintenant 1. Pensez-la comme un dur {b}, qui peut sauter.", "fl.h17": "Maintenant {b}. À 17 ou plus, tirer fait trop souvent sauter : on reste.", "fl.stiff": "Vous êtes entre 12 et 16 : tirer peut vous faire sauter. Le critère est la carte du croupier : {u}, {w}.", "fl.stiff2": "Toujours {b}. Comme avant, le {u} du croupier ({w}) décide.", "fl.low": "{b} ne peut pas encore sauter. Tirez pour la renforcer."});
Object.assign(I18N.pt, {"fl.h": "A situação mudou — pense de novo", "fl.hit": "Pediu com {a} → saiu {c}, agora {b}.", "fl.split": "Esta mão após dividir: recebeu {c}, agora {b}.", "fl.bust": "Estourar na próxima carta", "fl.ev": "Valor desta mão (antes → agora)", "fl.weak": "uma carta fraca (estoura muito)", "fl.strong": "uma carta forte (costuma fazer 17+)", "fl.21": "21: não dá para melhorar. Pare.", "fl.soft": "Ainda soft {b}: o ás pode voltar a valer 1, então outra carta não estoura.", "fl.softHard": "Contar o ás como 11 estouraria, então agora vale 1. Pense nela como hard {b}, que pode estourar.", "fl.h17": "Agora {b}. Com 17 ou mais, pedir estoura demais: o normal é parar.", "fl.stiff": "Você está em 12–16: pedir pode estourar. Quem decide é a carta do dealer: {u}, {w}.", "fl.stiff2": "Ainda {b}. Como antes, o {u} do dealer ({w}) decide.", "fl.low": "{b} ainda não estoura. Peça outra para fortalecer."});
Object.assign(I18N.de, {"fl.h": "Die Lage hat sich geändert — neu entscheiden", "fl.hit": "Karte auf {a} → {c} gezogen, jetzt {b}.", "fl.split": "Diese Hand nach dem Split: {c} erhalten, jetzt {b}.", "fl.bust": "Überkaufen mit der nächsten Karte", "fl.ev": "Wert dieser Hand (vorher → jetzt)", "fl.weak": "eine schwache Karte (überkauft oft)", "fl.strong": "eine starke Karte (macht oft 17+)", "fl.21": "21 – besser geht es nicht. Stehen.", "fl.soft": "Immer noch Soft {b}: Das Ass kann wieder 1 zählen, eine Karte mehr kann nicht überkaufen.", "fl.softHard": "Ass als 11 würde überkaufen, also zählt es jetzt 1. Denken Sie neu: Hard {b}, das überkaufen kann.", "fl.h17": "Jetzt {b}. Ab 17 überkauft Ziehen zu oft – stehen bleiben.", "fl.stiff": "Sie sind bei 12–16: Ziehen kann überkaufen. Entscheidend ist die Dealer-Karte {u}, {w}.", "fl.stiff2": "Immer noch {b}. Wie zuvor entscheidet die {u} des Dealers ({w}).", "fl.low": "{b} kann noch nicht überkaufen. Ziehen Sie, um die Hand zu stärken."});
Object.assign(I18N.hi, {"fl.h": "स्थिति बदल गई — फिर से सोचें", "fl.hit": "{a} पर हिट → {c} मिला, अब {b}।", "fl.split": "स्प्लिट के बाद यह हाथ: {c} मिला, अब {b}।", "fl.bust": "अगले कार्ड पर बस्ट", "fl.ev": "इस हाथ का मूल्य (पहले → अब)", "fl.weak": "कमज़ोर कार्ड (अक्सर बस्ट)", "fl.strong": "मज़बूत कार्ड (अक्सर 17+)", "fl.21": "21 — इससे बेहतर नहीं। स्टैंड।", "fl.soft": "अभी भी सॉफ्ट {b}: इक्का फिर 1 गिना जा सकता है, एक और कार्ड से बस्ट नहीं होंगे।", "fl.softHard": "इक्का 11 गिनने से बस्ट होता, इसलिए अब 1 है। इसे हार्ड {b} मानकर फिर सोचें।", "fl.h17": "अब {b}। 17 या अधिक पर हिट करने से अक्सर बस्ट — स्टैंड करें।", "fl.stiff": "अब 12–16: हिट करने से बस्ट हो सकते हैं। फ़ैसला डीलर के {u} से, {w}।", "fl.stiff2": "अभी भी {b}। पहले की तरह डीलर का {u} ({w}) तय करता है।", "fl.low": "{b} अभी बस्ट नहीं हो सकता। मज़बूत करने के लिए एक और कार्ड लें।"});
Object.assign(I18N.ar, {"fl.h": "تغيّر الموقف — فكّر من جديد", "fl.hit": "سحبت على {a} ← جاءت {c}، الآن {b}.", "fl.split": "هذه اليد بعد التقسيم: جاءت {c}، الآن {b}.", "fl.bust": "التجاوز بالورقة التالية", "fl.ev": "قيمة هذه اليد (قبل ← الآن)", "fl.weak": "ورقة ضعيفة (تتجاوز كثيرًا)", "fl.strong": "ورقة قوية (تصل غالبًا إلى 17+)", "fl.21": "21 — لا يمكن أفضل. توقّف.", "fl.soft": "ما زالت لينة {b}: يمكن عدّ الآص 1، فلن تتجاوز بورقة أخرى.", "fl.softHard": "عدّ الآص 11 يتجاوز، لذا صار 1. فكّر فيها كيد صلبة {b} يمكن أن تتجاوز.", "fl.h17": "الآن {b}. من 17 فما فوق يتجاوز السحب كثيرًا — توقّف.", "fl.stiff": "أنت الآن بين 12 و16: السحب قد يتجاوز. الحَكَم ورقة الموزّع {u}، {w}.", "fl.stiff2": "ما زالت {b}. كما سبق، ورقة الموزّع {u} ({w}) تقرّر.", "fl.low": "{b} لا يمكن أن تتجاوز بعد. اسحب لتقويتها."});
